    #[test]
    fn an_ocw_aside_with_a_year_lays_out() {
        let path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../corpus/cache/ocw-18-225-lec01.pdf");
        if !path.is_file() {
            return;
        }
        let pdf = PdfDocument::open(&path).unwrap();
        let extraction = pdf.extract();
        let seg = crate::segment::segment_placed(
            &extraction.glyphs,
            &crate::segment::SegmentFlags::default(),
            &extraction.regions,
            &extraction.pages,
        );
        let segment = seg
            .segments
            .iter()
            .find(|item| item.text.contains("Additive combinatorics describes"))
            .expect("paragraph");
        let translated = "加性组合学描述了一个快速发展的数学领域，其动机源于关于整数加法和乘法的简单问题。（“加性组合学”这一名称在2000年代变得流行，当时该领域因高尔斯、格林、陶哲轩等人的开创性工作而迅速爆发；此前该领域更常被称为“组合数论”。）加性组合学中的问题和方法深刻且影响深远，连接了数学的许多不同领域，如图论、调和分析、遍历理论、离散几何和模型论。";
        let mut points: Vec<u32> = translated.chars().map(|ch| ch as u32).collect();
        points.sort_unstable();
        points.dedup();
        let font = subset_for_style(
            FaceStyle {
                serif: true,
                bold: false,
                italic: false,
            },
            &points,
            &FontSources::default(),
        )
        .expect("font");
        let glyphs: Vec<&Glyph> = segment
            .glyph_ids
            .iter()
            .filter_map(|id| extraction.glyphs.iter().find(|glyph| glyph.id == *id))
            .collect();
        let drawn = layout_segment(
            &glyphs,
            translated,
            &font,
            &extraction,
            false,
            "RPT",
            0.0,
            CjkMeasure::resolve(0.0, 0.0),
        )
        .expect("paragraph fits");
        assert!(
            drawn.len() <= 8,
            "aside still exploded into {} lines",
            drawn.len()
        );
    }

    #[test]
    fn a_multiline_prose_paragraph_is_not_chained_into_a_formula() {
        // `ϕ(aim) = ϕ(ajr)` sits one line from Alignment Framework. The
        // formula stays a block. The paragraph is several lines of prose.
        let formula = super::MathSpan {
            page: 0,
            top: 360.0,
            bottom: 350.0,
            left: 72.0,
            right: 288.0,
            columns: None,
            size: 10.0,
            structural: true,
            letters: 8,
            head_left: 72.0,
            margin_left: 72.0,
        };
        let prose = super::MathSpan {
            page: 0,
            top: 348.0,
            bottom: 280.0,
            left: 72.0,
            right: 288.0,
            columns: None,
            size: 10.0,
            structural: false,
            letters: 200,
            head_left: 72.0,
            margin_left: 72.0,
        };
        let shard = super::MathSpan {
            page: 0,
            top: 348.0,
            bottom: 348.0,
            left: 72.0,
            right: 200.0,
            columns: None,
            size: 10.0,
            structural: false,
            letters: 12,
            head_left: 72.0,
            margin_left: 72.0,
        };
        let bullet = super::MathSpan {
            page: 0,
            top: 336.0,
            bottom: 336.0,
            left: 72.0,
            right: 288.0,
            columns: None,
            size: 10.0,
            structural: false,
            letters: 44,
            head_left: 72.0,
            margin_left: 72.0,
        };
        assert!(
            !super::math_spans_chain(&formula, &prose),
            "the prose paragraph joined the formula"
        );
        assert!(
            !super::math_spans_chain(&formula, &bullet),
            "the scoring bullet joined the formula"
        );
        assert!(
            super::math_spans_chain(&formula, &shard),
            "a one-line formula fragment was released"
        );
    }

