    struct InkRow {
        y: f32,
        text: String,
        glyphs: Vec<InkSpot>,
    }

    struct InkSpot {
        text: String,
        x: f32,
        advance: f32,
        skew: f32,
    }

    fn letter_glyph(id: u32, x: f32, advance: f32, ink: f32, text: &str) -> Glyph {
        let mut glyph = ink_glyph(id, x, 400.0, 9.5, text);
        glyph.advance = [advance, 0.0];
        glyph.bbox = [x, 398.0, x + ink, 408.0];
        glyph
    }

    fn ink_of(glyphs: &[Glyph]) -> InkLine<'_> {
        let left = glyphs
            .iter()
            .map(|glyph| glyph.matrix[4])
            .fold(f32::MAX, f32::min);
        let right = glyphs
            .iter()
            .map(|glyph| glyph.bbox[2])
            .fold(left, f32::max);
        InkLine {
            glyphs: glyphs.iter().collect(),
            y: 400.0,
            left,
            right,
        }
    }

    fn ink_glyph(id: u32, x: f32, y: f32, size: f32, text: &str) -> Glyph {
        Glyph {
            id,
            page_index: 0,
            unicode: text.into(),
            unmapped: false,
            char_code: vec![b'A'],
            gid: None,
            font_resource: "F1".into(),
            font_name: "Times-Roman".into(),
            font_object: None,
            font_size: size,
            matrix: [size, 0.0, 0.0, size, x, y],
            bbox: [x, y - size * 0.2, x + size * 0.5, y + size * 0.8],
            advance: [size * 0.5, 0.0],
            fill_color: Color::black(),
            stroke_color: Color::black(),
            render_mode: 0,
            invisible: false,
            clipped: false,
            clip_uncertain: false,
            vertical: false,
            disposition: Disposition::Pending,
            source: GlyphSource {
                kind: SourceKind::PageContent,
                object_id: None,
                stream_index: 0,
                operator_index: 0,
                byte_start: 0,
                byte_end: 1,
                resource_name: Some("F1".into()),
            },
        }
    }

