    #[test]
    fn a_padded_slide_line_stays_centered_after_quotes_are_detached() {
        let mut glyphs = Vec::new();
        let mut id = 0u32;
        let mut push = |x: f32, y: f32, text: &str| {
            glyphs.push(ink_glyph(id, x, y, 20.0, text));
            id += 1;
        };
        for (row, text) in [
            (300.0, "Rust, Security, Social,"),
            (276.0, "Swift, Testing, Storage,"),
            (252.0, "WebAssembly, Web,"),
        ]
        .iter()
        {
            let width = text.chars().count() as f32 * 10.0;
            let mut x = 360.0 - width * 0.5;
            for ch in text.chars() {
                push(x, *row, &ch.to_string());
                x += 10.0;
            }
            if (*row - 252.0).abs() < 0.1 {
                // The pad continues the line, the way a slides text box does,
                // out past the page. A gap would make it a separate cluster.
                for step in 0..40 {
                    push(x + step as f32 * 10.0, *row, " ");
                }
            }
        }
        drop(push);
        let refs: Vec<&Glyph> = glyphs.iter().collect();
        let mut lines = super::ink_lines(&refs);
        assert!(
            super::centered_list_ink(&lines),
            "padding must not move the midpoint"
        );
        let _quotes = super::detach_decorative_quotes(&mut lines);
        assert!(
            super::centered_list_ink(&lines),
            "recomputing edges must ignore the slide pad"
        );
        let axis = super::centered_list_axis(&lines);
        let last = lines.last().unwrap();
        assert!(
            ((last.left + last.right) * 0.5 - axis).abs() < 30.0,
            "last line mid drifted to {}",
            (last.left + last.right) * 0.5
        );
        assert!(
            last.right < 600.0,
            "pad still in the right edge {}",
            last.right
        );
        let translated = "Rust、安全、社交、Swift、测试、存储、WebAssembly、Web 性能";
        let mut points: Vec<u32> = translated.chars().map(|ch| ch as u32).collect();
        points.sort_unstable();
        points.dedup();
        let Some(font) = subset_for_style(
            FaceStyle {
                serif: false,
                bold: false,
                italic: false,
            },
            &points,
            &FontSources::default(),
        ) else {
            return;
        };
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![crate::glyph::PageInfo {
                index: 0,
                object_id: "1 0".into(),
                media_box: [0.0, 0.0, 720.0, 405.0],
                rotate: 0,
            }],
            glyphs: glyphs.clone(),
            regions: Vec::new(),
            diagnostics: Vec::new(),
        };
        let drawn = super::layout_segment(
            &refs,
            translated,
            &font,
            &extraction,
            false,
            "RPT",
            0.0,
            CjkMeasure::resolve(0.90, 1.60),
        )
        .expect("list fits");
        assert!(drawn.len() >= 2, "list should wrap inside the box");
        for line in &drawn {
            let advance = line.widths.iter().sum::<f32>();
            let mid = line.x + advance * 0.5;
            assert!(
                (mid - axis).abs() < 8.0,
                "drawn line mid {mid:.1} left the axis {axis:.1}: {}",
                line.text
            );
        }
    }

    #[test]
    fn a_stacked_formula_keeps_the_surrounding_paragraph() {
        let mut glyphs = Vec::new();
        let mut id = 0u32;
        let mut push = |x: f32, y: f32, text: &str, font: &str| {
            let mut glyph = ink_glyph(id, x, y, 10.0, text);
            glyph.font_name = font.into();
            glyphs.push(glyph);
            id += 1;
        };
        for (index, ch) in "We use a potential".chars().enumerate() {
            push(
                72.0 + index as f32 * 5.0,
                700.0,
                &ch.to_string(),
                "LMRoman10",
            );
        }
        for (index, ch) in ["k", "+", "1", "2"].iter().enumerate() {
            // The `2` sits under `k+1`, inside one em. A full leading lower
            // would be the next line, which is not this binomial.
            let y = if *ch == "2" { 694.0 } else { 705.0 };
            push(200.0 + index as f32 * 6.0, y, ch, "LMMathItalic10");
        }
        for (index, ch) in "dimensional vector".chars().enumerate() {
            push(
                240.0 + index as f32 * 5.0,
                700.0,
                &ch.to_string(),
                "LMRoman10",
            );
        }
        push(
            72.0,
            400.0,
            "Unrelated paragraph about servers.",
            "LMRoman10",
        );
        drop(push);
        let near: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| glyph.id != id - 1)
            .map(|glyph| glyph.id)
            .collect();
        let far_id = id - 1;
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![crate::glyph::PageInfo {
                index: 0,
                object_id: "1 0".into(),
                media_box: [0.0, 0.0, 612.0, 792.0],
                rotate: 0,
            }],
            glyphs,
            regions: Vec::new(),
            diagnostics: Vec::new(),
        };
        let by_id = glyph_index(&extraction.glyphs);
        let report = crate::translate::TranslateReport {
            segments: vec![
                crate::translate::TranslatedSegment {
                    id: 0,
                    page_index: 0,
                    glyph_ids: near,
                    source: "We use a potential".into(),
                    translated: "我们使用势".into(),
                },
                crate::translate::TranslatedSegment {
                    id: 1,
                    page_index: 0,
                    glyph_ids: vec![far_id],
                    source: "Unrelated paragraph about servers.".into(),
                    translated: "无关段落".into(),
                },
            ],
            calls: 0,
            cache_hits: 0,
        };
        let blocks = super::math_block_segments(&report, &extraction, &by_id);
        assert!(blocks.contains(&0), "the stacked formula was reflowed");
        assert!(!blocks.contains(&1), "a distant paragraph was kept as math");
    }

    #[test]
    fn italic_k_on_successive_lines_is_not_a_stacked_formula() {
        let mut glyphs = Vec::new();
        let mut id = 0u32;
        let mut push = |x: f32, y: f32, text: &str, font: &str| {
            let mut glyph = ink_glyph(id, x, y, 10.0, text);
            glyph.font_name = font.into();
            glyphs.push(glyph);
            id += 1;
        };
        for y in [700.0, 686.0, 672.0] {
            push(72.0, y, "k", "LMMathItalic10");
            for (index, ch) in "server problem stays prose here".chars().enumerate() {
                push(90.0 + index as f32 * 5.0, y, &ch.to_string(), "LMRoman10");
            }
        }
        // A real binomial on the last line. The paragraph stays original.
        // The indented paragraph one leading below must still translate.
        for (index, ch) in ["k", "+", "1", "2"].iter().enumerate() {
            let y = if *ch == "2" { 668.0 } else { 676.0 };
            push(250.0 + index as f32 * 6.0, y, ch, "LMMathItalic10");
        }
        for (index, ch) in "The check that the potential holds.".chars().enumerate() {
            push(
                90.0 + index as f32 * 5.0,
                658.0,
                &ch.to_string(),
                "LMRoman10",
            );
        }
        drop(push);
        let prose: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| glyph.matrix[5] >= 660.0)
            .map(|glyph| glyph.id)
            .collect();
        let next: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| glyph.matrix[5] < 660.0)
            .map(|glyph| glyph.id)
            .collect();
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![crate::glyph::PageInfo {
                index: 0,
                object_id: "1 0".into(),
                media_box: [0.0, 0.0, 612.0, 792.0],
                rotate: 0,
            }],
            glyphs,
            regions: Vec::new(),
            diagnostics: Vec::new(),
        };
        let by_id = glyph_index(&extraction.glyphs);
        let report = crate::translate::TranslateReport {
            segments: vec![
                crate::translate::TranslatedSegment {
                    id: 0,
                    page_index: 0,
                    glyph_ids: prose,
                    source: "k server problem".into(),
                    translated: "k 服务器问题".into(),
                },
                crate::translate::TranslatedSegment {
                    id: 1,
                    page_index: 0,
                    glyph_ids: next,
                    source: "The check that the potential holds.".into(),
                    translated: "验证势函数成立。".into(),
                },
            ],
            calls: 0,
            cache_hits: 0,
        };
        let blocks = super::math_block_segments(&report, &extraction, &by_id);
        assert!(blocks.contains(&0), "the binomial paragraph was reflowed");
        assert!(
            !blocks.contains(&1),
            "the indented paragraph was kept as math"
        );
    }

    #[test]
    fn a_display_equation_keeps_the_heading_across_a_placeholder() {
        // Page 9: the display equation sits under the ⟦N⟧ paragraph, and the
        // section heading sits above it. Walking through the placeholder
        // keeps the heading in its source glyphs. Cutting the walk paints
        // the Chinese heading onto the binomial.
        let mut glyphs = Vec::new();
        let mut id = 0u32;
        let mut push = |x: f32, y: f32, text: &str, font: &str| {
            let mut glyph = ink_glyph(id, x, y, 10.0, text);
            glyph.font_name = font.into();
            glyphs.push(glyph);
            id += 1;
        };
        for (index, ch) in "4 The potential and its increase".chars().enumerate() {
            push(
                72.0 + index as f32 * 5.0,
                400.0,
                &ch.to_string(),
                "LMRoman10",
            );
        }
        for (index, ch) in "Fix any total order on the labels".chars().enumerate() {
            push(
                72.0 + index as f32 * 5.0,
                388.0,
                &ch.to_string(),
                "LMRoman10",
            );
        }
        for (index, ch) in ["Q", "=", "z", "q", "x"].iter().enumerate() {
            push(72.0 + index as f32 * 8.0, 376.0, ch, "LMMathItalic10");
        }
        drop(push);
        let heading: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| glyph.matrix[5] > 394.0)
            .map(|glyph| glyph.id)
            .collect();
        let middle: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| (glyph.matrix[5] - 388.0).abs() < 2.0)
            .map(|glyph| glyph.id)
            .collect();
        let display: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| glyph.matrix[5] < 382.0)
            .map(|glyph| glyph.id)
            .collect();
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![crate::glyph::PageInfo {
                index: 0,
                object_id: "1 0".into(),
                media_box: [0.0, 0.0, 612.0, 792.0],
                rotate: 0,
            }],
            glyphs,
            regions: Vec::new(),
            diagnostics: Vec::new(),
        };
        let by_id = glyph_index(&extraction.glyphs);
        let report = crate::translate::TranslateReport {
            segments: vec![
                crate::translate::TranslatedSegment {
                    id: 0,
                    page_index: 0,
                    glyph_ids: heading,
                    source: "4 The potential and its increase".into(),
                    translated: "4 请求时的势及其增量".into(),
                },
                crate::translate::TranslatedSegment {
                    id: 1,
                    page_index: 0,
                    glyph_ids: middle,
                    source: "Fix any total order on the labels".into(),
                    translated: "固定有限标签集 ⟦0⟧".into(),
                },
                crate::translate::TranslatedSegment {
                    id: 2,
                    page_index: 0,
                    glyph_ids: display,
                    source: "Q = z q x".into(),
                    translated: "Q = z q x".into(),
                },
            ],
            calls: 0,
            cache_hits: 0,
        };
        let blocks = super::math_block_segments(&report, &extraction, &by_id);
        assert!(
            blocks.contains(&0),
            "a regular line that starts with a digit was released"
        );
        assert!(blocks.contains(&2), "the display equation was reflowed");
        // The synthetic heading is regular roman at body size. The paper's
        // section head is bold, which is what releases it.
        let mut bold_glyphs = extraction.glyphs.clone();
        for glyph in &mut bold_glyphs {
            if glyph.matrix[5] > 394.0 {
                glyph.font_name = "LMRoman12-Bold".into();
            }
        }
        let bold_report = crate::translate::TranslateReport {
            segments: report.segments.clone(),
            calls: 0,
            cache_hits: 0,
        };
        let by_bold = glyph_index(&bold_glyphs);
        let extraction_bold = Extraction {
            glyphs: bold_glyphs,
            ..extraction
        };
        let released = super::math_block_segments(&bold_report, &extraction_bold, &by_bold);
        assert!(
            !released.contains(&0),
            "a bold section heading was kept as a math block"
        );
        assert!(
            released.contains(&2),
            "releasing the heading reflowed the display"
        );
    }

    #[test]
    fn an_otherwise_clause_on_a_formula_is_not_kept_as_math() {
        let mut glyphs = Vec::new();
        let mut id = 0u32;
        let mut push = |x: f32, y: f32, text: &str, font: &str| {
            let mut glyph = ink_glyph(id, x, y, 10.0, text);
            glyph.font_name = font.into();
            glyphs.push(glyph);
            id += 1;
        };
        // Ten formula glyphs, nine roman letters. The line is a math shard
        // unless the otherwise clause releases it.
        for (index, ch) in "φ(a)=φ(a)+k".chars().enumerate() {
            push(
                40.0 + index as f32 * 8.0,
                400.0,
                &ch.to_string(),
                "LMMathItalic10",
            );
        }
        for (index, ch) in "otherwise".chars().enumerate() {
            push(
                140.0 + index as f32 * 6.0,
                400.0,
                &ch.to_string(),
                "LMRoman10",
            );
        }
        for (index, ch) in ["Q", "=", "z", "q"].iter().enumerate() {
            push(72.0 + index as f32 * 8.0, 200.0, ch, "LMMathItalic10");
        }
        drop(push);
        let clause: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| glyph.matrix[5] > 300.0)
            .map(|glyph| glyph.id)
            .collect();
        let display: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| glyph.matrix[5] < 300.0)
            .map(|glyph| glyph.id)
            .collect();
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![crate::glyph::PageInfo {
                index: 0,
                object_id: "1 0".into(),
                media_box: [0.0, 0.0, 612.0, 792.0],
                rotate: 0,
            }],
            glyphs,
            regions: Vec::new(),
            diagnostics: Vec::new(),
        };
        let by_id = glyph_index(&extraction.glyphs);
        let report = crate::translate::TranslateReport {
            segments: vec![
                crate::translate::TranslatedSegment {
                    id: 0,
                    page_index: 0,
                    glyph_ids: clause,
                    source: "phi = phi and 0 otherwise.".into(),
                    translated: "phi = phi，否则为 0。".into(),
                },
                crate::translate::TranslatedSegment {
                    id: 1,
                    page_index: 0,
                    glyph_ids: display,
                    source: "Q = z q".into(),
                    translated: "Q = z q".into(),
                },
            ],
            calls: 0,
            cache_hits: 0,
        };
        let blocks = super::math_block_segments(&report, &extraction, &by_id);
        assert!(
            blocks.contains(&0),
            "the formula around the otherwise clause was reflowed"
        );
        assert_eq!(
            super::formula_clause_text(&report.segments[0].source, &report.segments[0].translated)
                .as_deref(),
            Some("，否则为 0。")
        );
        assert!(blocks.contains(&1), "the display equation was reflowed");
    }

    #[test]
    fn a_numbered_heading_stays_above_its_paragraph() {
        // The paragraph above the heading is pulled up off its formula. The
        // heading's own source gap is only one leading, so it used to inherit
        // that pull and land on U∗. The next paragraph then left n+1/k+1.
        // U∗ is a script on the paragraph line, inside the inherited pull.
        let mut formula = ink_glyph(2, 340.0, 470.0, 10.0, "U");
        formula.font_name = "LMMathItalic10".into();
        let mut script = ink_glyph(4, 80.0, 424.0, 7.0, "∗");
        script.font_name = "LMMathSymbols8".into();
        let mut heading = ink_glyph(10, 72.0, 400.0, 14.3, "4");
        heading.font_name = "LMRoman12-Bold".into();
        let glyphs = vec![
            ink_glyph(1, 72.0, 500.0, 10.0, "A"),
            ink_glyph(3, 72.0, 430.0, 10.0, "W"),
            formula,
            script,
            heading,
            ink_glyph(20, 72.0, 378.0, 10.0, "F"),
        ];
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![],
            glyphs,
            regions: vec![],
            diagnostics: vec![],
        };
        let by_id = glyph_index(&extraction.glyphs);
        let mut drawn = vec![
            test_draw(72.0, 500.0, 10.0, "上文", vec![1]),
            test_draw(72.0, 430.0, 10.0, "块上三角", vec![3, 2, 4]),
            test_draw(72.0, 400.0, 14.3, "4 请求时的势及其增量", vec![10]),
            test_draw(91.0, 378.0, 10.0, "固定有限标签集", vec![20]),
        ];
        close_column_holes(&mut drawn, &extraction, &by_id);
        let heading_y = drawn
            .iter()
            .find(|item| item.text.starts_with('4'))
            .unwrap()
            .y;
        let body_y = drawn
            .iter()
            .find(|item| item.text.starts_with('固'))
            .unwrap()
            .y;
        assert!(
            (heading_y - 400.0).abs() < 0.5,
            "the heading left its baseline: {heading_y}"
        );
        assert!(
            (body_y - 378.0).abs() < 0.5,
            "the paragraph under the heading moved: {body_y}"
        );
    }

