    #[test]
    fn a_column_gutter_does_not_pull_prose_into_the_notation_stack() {
        // Left column ends, then 1.2em of gutter, then a binomial in the
        // other column. That gap is not the space after a stack.
        let mut glyphs = Vec::new();
        let mut id = 0u32;
        let mut push = |x: f32, y: f32, size: f32, text: &str, font: &str| {
            let mut glyph = ink_glyph(id, x, y, size, text);
            glyph.font_name = font.into();
            glyphs.push(glyph);
            id += 1;
        };
        let mut x = 60.0f32;
        for ch in "Despite these advances, existing methods either treat esti-".chars() {
            push(x, 700.0, 10.0, &ch.to_string(), "NimbusRom");
            x += 4.2;
        }
        let left_end = x;
        let stack_x = left_end + 12.0;
        for (index, ch) in ["k", "+", "1"].iter().enumerate() {
            push(
                stack_x + index as f32 * 6.0,
                705.0,
                8.0,
                ch,
                "LMMathItalic10",
            );
        }
        push(stack_x + 8.0, 694.0, 8.0, "2", "LMMathItalic10");
        push(stack_x - 4.0, 710.0, 10.0, "", "LMMathExtension10");
        push(stack_x + 16.0, 710.0, 10.0, "", "LMMathExtension10");
        let mut rx = stack_x + 40.0;
        for ch in "numbers".chars() {
            push(rx, 700.0, 10.0, &ch.to_string(), "NimbusRom");
            rx += 4.2;
        }
        drop(push);
        let left: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| glyph.matrix[4] < left_end && !glyph.unicode.is_empty())
            .map(|glyph| glyph.id)
            .collect();
        let stack: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| glyph.font_name.contains("Math"))
            .map(|glyph| glyph.id)
            .collect();
        let segments = vec![
            crate::segment::Segment {
                id: 0,
                page_index: 0,
                glyph_ids: left,
                text: "Despite these advances, existing methods either treat esti-".into(),
            },
            crate::segment::Segment {
                id: 1,
                page_index: 0,
                glyph_ids: stack,
                text: String::new(),
            },
        ];
        let merged = merge_stacked_paragraphs(segments, &glyphs);
        let prose = merged
            .iter()
            .find(|item| item.text.contains("Despite"))
            .expect("prose");
        assert!(
            !prose.text.contains("numbers"),
            "gutter joined the columns: {}",
            prose.text
        );
    }

    #[test]
    fn a_two_column_proof_is_not_held_as_a_math_block() {
        let path = std::path::Path::new("/tmp/enduser/2610.20248.pdf");
        if !path.exists() {
            return;
        }
        let doc = crate::extract::PdfDocument::open(path).unwrap();
        let extraction = doc.extract();
        let placed = crate::segment::segment_placed(
            &extraction.glyphs,
            &crate::segment::SegmentFlags::default(),
            &extraction.regions,
            &extraction.pages,
        );
        let merged = merge_stacked_paragraphs(placed.segments, &extraction.glyphs);
        let segments: Vec<crate::translate::TranslatedSegment> = merged
            .into_iter()
            .map(|seg| crate::translate::TranslatedSegment {
                id: seg.id,
                page_index: seg.page_index,
                glyph_ids: seg.glyph_ids,
                translated: "译文".into(),
                source: seg.text,
            })
            .collect();
        let report = crate::translate::TranslateReport {
            segments,
            calls: 0,
            cache_hits: 0,
        };
        let by_id = glyph_index(&extraction.glyphs);
        let blocks = super::math_block_segments(&report, &extraction, &by_id);
        let held = |needle: &str| {
            report
                .segments
                .iter()
                .enumerate()
                .any(|(index, seg)| blocks.contains(&index) && seg.source.contains(needle))
        };
        assert!(!held("Despite these advances"), "intro stayed a math block");
        assert!(
            !held("tractable design procedure"),
            "intro close stayed a math block"
        );
        assert!(
            !held("Conceptual figure"),
            "figure caption stayed a math block"
        );
        assert!(
            !held("then the feedback interconnection"),
            "page 7 proof stayed a math block"
        );
        assert!(
            !held("unstructured dynamic uncertainty"),
            "page 9 uncertainty set stayed a math block"
        );
        assert!(
            !held("We over-approximate"),
            "page 9 estimate stayed a math block"
        );
        assert!(
            !held("This result represents"),
            "page 7 discussion stayed a math block"
        );
        assert!(
            !held("Despite this progress"),
            "page 7 convexity paragraph stayed a math block"
        );
    }

    #[test]
    fn a_binomial_paragraph_becomes_one_placeholder_segment() {
        let mut glyphs = Vec::new();
        let mut id = 0u32;
        let mut push = |x: f32, y: f32, size: f32, text: &str, font: &str| {
            let mut glyph = ink_glyph(id, x, y, size, text);
            glyph.font_name = font.into();
            glyphs.push(glyph);
            id += 1;
        };
        let mut x = 72.0f32;
        for ch in "We use a potential ".chars() {
            push(x, 700.0, 10.0, &ch.to_string(), "LMRoman10");
            x += 5.0;
        }
        let stack_x = x;
        for (index, ch) in ["k", "+", "1"].iter().enumerate() {
            push(
                stack_x + index as f32 * 6.0,
                705.0,
                8.0,
                ch,
                "LMMathItalic10",
            );
        }
        push(stack_x + 8.0, 694.0, 8.0, "2", "LMMathItalic10");
        // Latin Modern draws the binomial fences as empty extension glyphs
        // above the numerator. They are part of the stack, not a baseline.
        push(stack_x - 4.0, 710.0, 10.0, "", "LMMathExtension10");
        push(stack_x + 16.0, 710.0, 10.0, "", "LMMathExtension10");
        x = stack_x + 22.0;
        for ch in " dimensional vector.".chars() {
            push(x, 700.0, 10.0, &ch.to_string(), "LMRoman10");
            x += 5.0;
        }
        // q_x on the line above shares the binomial's x. It stays in the
        // sentence. The µ is a formula glyph the segmenter left out.
        let mut above_x = 72.0f32;
        for ch in "vectors ".chars() {
            push(above_x, 714.0, 10.0, &ch.to_string(), "LMRoman10");
            above_x += 5.0;
        }
        push(stack_x, 714.0, 10.0, "q", "LMMathItalic10");
        push(stack_x + 5.0, 712.5, 8.0, "x", "LMMathItalic10");
        push(400.0, 700.0, 10.0, "µ", "LMMathItalic10");
        let mut cont_x = 72.0f32;
        for ch in "by pairs here.".chars() {
            push(cont_x, 686.0, 10.0, &ch.to_string(), "LMRoman10");
            cont_x += 5.0;
        }
        let mut next_x = 90.0f32;
        for ch in "The check holds.".chars() {
            push(next_x, 674.0, 10.0, &ch.to_string(), "LMRoman10");
            next_x += 5.0;
        }
        drop(push);
        // The source line is one column. A segment box that stops at the
        // binomial would not overlap it, and the paragraph would not merge.
        if let Some(glyph) = glyphs.iter_mut().find(|glyph| glyph.unicode == "W") {
            glyph.bbox[2] = 540.0;
        }
        if let Some(glyph) = glyphs.iter_mut().find(|glyph| glyph.unicode == "k") {
            glyph.bbox[2] = 540.0;
        }
        let prose: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| {
                glyph.font_name == "LMRoman10"
                    && glyph.matrix[4] < stack_x
                    && (690.0..710.0).contains(&glyph.matrix[5])
            })
            .map(|glyph| glyph.id)
            .collect();
        let stack: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| {
                glyph.font_name.contains("Math")
                    && (690.0..710.0).contains(&glyph.matrix[5])
                    && glyph.matrix[4] >= stack_x - 1.0
            })
            .map(|glyph| glyph.id)
            .collect();
        let tail: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| {
                glyph.font_name == "LMRoman10"
                    && glyph.matrix[4] >= stack_x
                    && glyph.matrix[5] > 690.0
            })
            .map(|glyph| glyph.id)
            .collect();
        let above: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| glyph.matrix[5] > 710.0)
            .map(|glyph| glyph.id)
            .collect();
        let continuation: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| (680.0..690.0).contains(&glyph.matrix[5]))
            .map(|glyph| glyph.id)
            .collect();
        let next: Vec<u32> = glyphs
            .iter()
            .filter(|glyph| glyph.matrix[5] < 680.0)
            .map(|glyph| glyph.id)
            .collect();
        let segments = vec![
            crate::segment::Segment {
                id: 0,
                page_index: 0,
                glyph_ids: prose,
                text: "We use a potential".into(),
            },
            crate::segment::Segment {
                id: 1,
                page_index: 0,
                glyph_ids: stack.clone(),
                text: "k+21".into(),
            },
            crate::segment::Segment {
                id: 2,
                page_index: 0,
                glyph_ids: tail,
                text: "dimensional vector.".into(),
            },
            crate::segment::Segment {
                id: 3,
                page_index: 0,
                glyph_ids: above,
                text: "q x".into(),
            },
            crate::segment::Segment {
                id: 4,
                page_index: 0,
                glyph_ids: continuation,
                text: "by pairs here.".into(),
            },
            crate::segment::Segment {
                id: 5,
                page_index: 0,
                glyph_ids: next,
                text: "The check holds.".into(),
            },
        ];
        let merged = super::merge_stacked_paragraphs(segments, &glyphs);
        assert_eq!(merged.len(), 2, "{merged:?}");
        let paragraph = merged
            .iter()
            .find(|segment| segment.text.contains('⟦'))
            .unwrap_or_else(|| panic!("no placeholder: {merged:?}"));
        assert!(
            paragraph.text.contains("⟦0⟧"),
            "stack was linearized: {}",
            paragraph.text
        );
        assert!(
            !paragraph.text.contains("k+21"),
            "bad linearization survived: {}",
            paragraph.text
        );
        let potential = paragraph.text.find("potential").expect(&paragraph.text);
        let dimensional = paragraph.text.find("dimensional").expect(&paragraph.text);
        let placeholder = paragraph.text[potential..dimensional]
            .find('⟦')
            .map(|offset| potential + offset)
            .unwrap_or_else(|| panic!("{}", paragraph.text));
        assert!(
            potential < placeholder && placeholder < dimensional,
            "the binomial hole left its line: {}",
            paragraph.text
        );
        assert!(
            paragraph.text.contains("vectors")
                && paragraph.text.find("vectors").unwrap() < potential
                && !paragraph.text.contains("q ⟦")
                && !paragraph.text.contains("qx ⟦")
                && !paragraph.text.contains("qx"),
            "the subscript above the binomial was flattened or swallowed: {}",
            paragraph.text
        );
        assert!(
            paragraph.text.contains('µ'),
            "orphan formula was left out: {}",
            paragraph.text
        );
        assert!(
            merged.iter().any(|segment| segment.text.contains("check")),
            "the indented paragraph was merged: {merged:?}"
        );
        assert!(paragraph.glyph_ids.len() > stack.len());
    }

    #[test]
    fn adjacent_formula_holes_keep_their_scripts() {
        let mut glyphs = Vec::new();
        let mut id = 0u32;
        let mut push = |x: f32, y: f32, size: f32, text: &str, font: &str| {
            let mut glyph = ink_glyph(id, x, y, size, text);
            glyph.font_name = font.into();
            glyph.bbox = [x, y - size * 0.2, x + size * 0.5, y + size * 0.8];
            glyphs.push(glyph);
            id += 1;
        };
        let mut x = 72.0f32;
        for ch in "We use a potential ".chars() {
            push(x, 400.0, 10.0, &ch.to_string(), "LMRoman10");
            x += 5.0;
        }
        push(220.0, 400.0, 10.0, "q", "LMMathItalic10");
        push(226.0, 396.0, 7.0, "x", "LMMathItalic10");
        push(250.0, 400.0, 10.0, "g", "LMMathItalic10");
        push(256.0, 396.0, 7.0, "1", "LMMathItalic10");
        drop(push);
        let refs: Vec<&Glyph> = glyphs.iter().collect();
        let body = super::prose_body_size(&refs);
        let groups = super::placeholder_groups(&refs, body);
        assert_eq!(groups.len(), 2, "scripts were not two holes: {groups:?}");
        let mut codes = std::collections::HashMap::new();
        for (gid, ch) in (1u16..).zip("前词后0123456789　".chars()) {
            codes.insert(ch as u32, (gid, 1000u16));
        }
        let font = crate::font::SubsetFont {
            bytes: Vec::new(),
            units_per_em: 1000,
            glyphs: codes,

            fallback: None,
            notice: None,
        };
        let (expanded, holes) = super::expand_stack_placeholders("前⟦0⟧⟦1⟧后", &refs, &font);
        assert!(
            expanded.contains('0') && expanded.contains('\u{3000}') && expanded.contains('后'),
            "adjacent holes merged or dropped: {expanded}"
        );
        assert!(
            !expanded.contains("\u{3000}\u{3000}"),
            "a hole reserved more than its math: {expanded}"
        );
        assert!(
            holes
                .get(&0)
                .is_some_and(|width| *width < 12.0 && *width > 8.0),
            "q_x was padded out to an em: {holes:?}"
        );
        assert!(
            expanded
                .find("00")
                .is_some_and(|at| expanded[at..].contains("01")),
            "the second formula lost its index: {expanded}"
        );
        let wrapped = crate::layout::wrap_text(&expanded, 10.0, 80.0, 80.0, &font).expect("wrap");
        let kept = wrapped.join("");
        assert!(
            kept.contains('\u{3000}'),
            "wrap trimmed the formula hole: {wrapped:?}"
        );
        let trailing =
            crate::layout::wrap_text("并且\u{3000}\u{3000}\u{3000}", 10.0, 200.0, 200.0, &font)
                .expect("trailing");
        assert!(
            trailing.iter().any(|line| line.contains('\u{3000}')),
            "a trailing hole was trimmed: {trailing:?}"
        );
        let chars = expanded.chars().count();
        let line = Drawn {
            page: 0,
            x: 72.0,
            y: 400.0,
            size: 10.0,
            color: Color::black(),
            cids: vec![1; chars],
            resource: "F1".into(),
            skew: 0.0,
            text: expanded.clone(),
            glyph_ids: Vec::new(),
            widths: vec![5.0; chars],
            gaps: vec![0.0; chars.saturating_sub(1)],
            supers: vec![false; chars],
            sup_scale: 1.0,
            sup_rise: 0.0,
        };
        let mut lines = vec![line];
        let shifts = super::lift_stack_placeholders(&mut lines, &refs, &font).expect("lift");
        assert_eq!(shifts.len(), 2);
        let q = glyphs.iter().find(|glyph| glyph.unicode == "q").unwrap().id;
        let g = glyphs.iter().find(|glyph| glyph.unicode == "g").unwrap().id;
        assert!(shifts.iter().any(|shift| shift.ids.contains(&q)));
        assert!(shifts.iter().any(|shift| shift.ids.contains(&g)));
        let painted: String = lines.iter().map(|item| item.text.as_str()).collect();
        assert!(
            !painted.contains('\u{3000}'),
            "hole stayed in the line: {painted}"
        );
        assert!(
            painted.contains('前') && painted.contains('后'),
            "{painted}"
        );
        assert!(
            wrapped
                .iter()
                .filter(|item| item.contains('\u{3000}'))
                .all(|item| { item.chars().any(|ch| ch.is_ascii_digit()) }),
            "the index split from its hole: {wrapped:?}"
        );
    }

    #[test]
    fn the_k_server_binomial_placeholder_sits_on_its_line() {
        let path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../corpus/cache/arxiv-2609.15979.pdf");
        if !path.is_file() {
            return;
        }
        let pdf = PdfDocument::open(&path).unwrap();
        let extracted = pdf.extract();
        let segmentation = crate::segment::segment_placed(
            &extracted.glyphs,
            &crate::segment::SegmentFlags::default(),
            &extracted.regions,
            &extracted.pages,
        );
        let merged = merge_stacked_paragraphs(segmentation.segments, &extracted.glyphs);
        let paragraph = merged
            .iter()
            .find(|segment| segment.page_index == 3 && segment.text.contains('⟦'))
            .unwrap_or_else(|| panic!("page 4 has no binomial placeholder"));
        let text = &paragraph.text;
        let before = text
            .find("which is a")
            .or_else(|| text.find("potential"))
            .unwrap_or_else(|| panic!("{text}"));
        let after = text.find("dimensional").unwrap_or_else(|| panic!("{text}"));
        let hole = text[before..after]
            .find('⟦')
            .map(|offset| before + offset)
            .unwrap_or_else(|| panic!("{text}"));
        assert!(
            before < hole && hole < after,
            "binomial hole left its line: {text}"
        );
        assert!(!text.contains("k+21"), "{text}");
        assert!(
            !text.contains("q ⟦") && !text.contains("qx ⟦"),
            "hole landed on the subscript: {text}"
        );
        assert!(
            text.contains('µ') || text.contains('μ'),
            "the inline potential was dropped: {text}"
        );
        assert!(
            !text.contains("z−d") && !text.contains("qxqy") && !text.contains("gi1"),
            "a script was flattened onto the baseline: {text}"
        );
        assert!(
            text.matches('⟦').count() >= 4,
            "script atoms were not holed: {text}"
        );
        let by_id = glyph_index(&extracted.glyphs);
        let owned: Vec<&Glyph> = paragraph
            .glyph_ids
            .iter()
            .filter_map(|id| extracted.glyphs.get(by_id[id]))
            .collect();
        let groups = super::placeholder_groups(&owned, super::prose_body_size(&owned));
        assert!(
            groups.iter().any(|ids| {
                let members: Vec<&Glyph> = ids
                    .iter()
                    .filter_map(|id| extracted.glyphs.get(by_id[id]))
                    .collect();
                let base = members
                    .iter()
                    .any(|glyph| glyph.unicode == "g" && glyph.font_size > 9.0);
                let sub = members
                    .iter()
                    .any(|glyph| glyph.unicode == "1" && glyph.font_size < 8.5);
                base && sub
            }),
            "g_i1 lost its subscript glyph"
        );
        let lemma = merged
            .iter()
            .find(|segment| segment.page_index == 8 && segment.text.contains("invertible"))
            .unwrap_or_else(|| panic!("lemma 3.2 item 1 was dropped"));
        assert!(
            lemma.text.contains('⟦'),
            "lemma 3.2 stayed a flat formula: {}",
            lemma.text
        );
        let page9 = merged
            .iter()
            .find(|segment| segment.page_index == 8 && segment.text.contains("matrix Q"))
            .unwrap_or_else(|| panic!("page 9 lost the binomial sentence: {merged:?}"));
        assert!(
            page9.text.contains("matrix Q")
                && page9.text.contains("where N")
                && page9.text.matches('⟦').count() >= 2
                && !page9.text.contains("k+21"),
            "page 9 binomials left their words: {}",
            page9.text
        );
    }

    #[test]
    fn the_k_server_page4_holes_match_the_math_and_fill_the_column() {
        let path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../corpus/cache/arxiv-2609.15979.pdf");
        if !path.is_file() {
            return;
        }
        let pdf = PdfDocument::open(&path).unwrap();
        let extracted = pdf.extract();
        let segmentation = crate::segment::segment_placed(
            &extracted.glyphs,
            &crate::segment::SegmentFlags::default(),
            &extracted.regions,
            &extracted.pages,
        );
        let merged = merge_stacked_paragraphs(segmentation.segments, &extracted.glyphs);
        let paragraph = merged
            .iter()
            .find(|segment| segment.page_index == 3 && segment.text.contains("which is a"))
            .unwrap_or_else(|| panic!("page 4 opening paragraph missing"));
        let translated = "我们现在可以仅以代数形式考虑该问题，因为工作函数和扩展代价可以只用向量 ⟦0⟧ 及其变换来表示。我们使用基于二次乘积 ⟦1⟧ 的势函数，它是一个 ⟦2⟧ 维向量，其坐标由数对 ⟦3⟧ 与 ⟦4⟧ 索引，其分量通过取 ⟦5⟧ 和 ⟦6⟧ 在各自坐标上的分量的乘积得到。该势函数为 Ψ = ⟦7⟧，其中 Q = ⟦8⟧⟦9⟧，且 ⟦10⟧ = ⟦11⟧ ν(det⟦12⟧⟦13⟧⟦14⟧。⟦15⟧ 项和 µ 函数与先前已知的用于证明 WFA 某些情形竞争性的势函数类似。其他势函数也使用了选择一个点子集来最小化一个表达式，该表达式包含工作函数值（这里通过 ⟦16⟧ 间接表示）以及所用点之间带负号的距离对（这里通过 ⟦17⟧ 表示）";
        let mut points: Vec<u32> = translated
            .chars()
            .map(|ch| ch as u32)
            .chain("0123456789　 Ψµμν()=，。、".chars().map(|ch| ch as u32))
            .collect();
        points.sort_unstable();
        points.dedup();
        let font = subset_for_style(
            FaceStyle {
                serif: true,
                bold: false,
                italic: false,
            },
            &points,
            &FontSources::default(),
        )
        .expect("cjk font");
        let by_id = glyph_index(&extracted.glyphs);
        let glyphs: Vec<&Glyph> = paragraph
            .glyph_ids
            .iter()
            .filter_map(|id| extracted.glyphs.get(by_id[id]))
            .collect();
        let column_right = glyphs
            .iter()
            .filter(|glyph| {
                glyph.font_size > 9.0 && glyph.unicode.chars().any(|ch| ch.is_ascii_alphabetic())
            })
            .map(|glyph| glyph.matrix[4] + glyph.advance[0].max(0.0))
            .fold(0.0f32, f32::max);
        assert!(
            (column_right - 540.0).abs() < 1.5,
            "page 4 column right drifted to {column_right:.1}"
        );
        let mut drawn = layout_segment(
            &glyphs,
            translated,
            &font,
            &extracted,
            false,
            "RPT",
            0.0,
            CjkMeasure::resolve(0.0, 0.0),
        )
        .unwrap_or_else(|| panic!("page 4 paragraph did not fit"));
        let shifts = lift_stack_placeholders(&mut drawn, &glyphs, &font)
            .unwrap_or_else(|| panic!("a formula hole was missing"));
        struct Slice {
            y: f32,
            x: f32,
            right: f32,
        }
        let mut slices: Vec<Slice> = Vec::new();
        for line in &drawn {
            let right = line.x + line.widths.iter().sum::<f32>() + line.gaps.iter().sum::<f32>();
            assert!(
                right <= column_right + 0.8,
                "text at y={:.1} ends at {right:.1}, past {column_right:.1}: {}",
                line.y,
                line.text
            );
            slices.push(Slice {
                y: line.y,
                x: line.x,
                right,
            });
        }
        let mut formulas: Vec<(f32, f32, f32, String)> = Vec::new();
        for shift in &shifts {
            let members: Vec<&Glyph> = shift
                .ids
                .iter()
                .filter_map(|id| extracted.glyphs.get(by_id[id]))
                .collect();
            let left = members
                .iter()
                .map(|glyph| glyph.matrix[4].min(glyph.bbox[0]))
                .fold(f32::MAX, f32::min);
            let math_right = members
                .iter()
                .map(|glyph| super::glyph_paint_right(glyph))
                .fold(left, f32::max)
                + shift.dx;
            let hole = left + shift.dx;
            let ink: String = members.iter().map(|glyph| glyph.unicode.as_str()).collect();
            assert!(
                math_right <= column_right + 0.8,
                "{ink:?} ends at {math_right:.1}, past {column_right:.1}"
            );
            formulas.push((hole, math_right, math_right - hole, ink));
        }
        let column_left = slices.iter().map(|slice| slice.x).fold(f32::MAX, f32::min);
        let mut ys: Vec<f32> = Vec::new();
        for slice in &slices {
            if !ys.iter().any(|y| (*y - slice.y).abs() < 0.8) {
                ys.push(slice.y);
            }
        }
        ys.sort_by(|left, right| right.total_cmp(left));
        let mut rows: Vec<(f32, f32, f32)> = Vec::new();
        for (row_index, y) in ys.iter().enumerate() {
            let mut on_line: Vec<&Slice> = slices
                .iter()
                .filter(|slice| (slice.y - y).abs() < 0.8)
                .collect();
            on_line.sort_by(|left, right| left.x.total_cmp(&right.x));
            let indent = row_index == 0;
            let mut gaps: Vec<(f32, f32)> = Vec::new();
            if !indent {
                if let Some(first) = on_line.first() {
                    if first.x > column_left + 1.5 {
                        gaps.push((column_left, first.x));
                    }
                }
            }
            for pair in on_line.windows(2) {
                if pair[1].x > pair[0].right + 1.5 {
                    gaps.push((pair[0].right, pair[1].x));
                }
            }
            for (gap_start, gap_end) in gaps {
                let gap = gap_end - gap_start;
                let mut cursor = gap_start;
                let mut covered = 0.0f32;
                let mut guard = 0;
                while cursor < gap_end - 0.8 {
                    let next = formulas
                        .iter()
                        .filter(|(hole, math_right, _, _)| {
                            (*hole - cursor).abs() <= 1.5 && *math_right <= gap_end + 1.5
                        })
                        .min_by(|(left_hole, _, _, _), (right_hole, _, _, _)| {
                            (*left_hole - cursor)
                                .abs()
                                .total_cmp(&(*right_hole - cursor).abs())
                        });
                    let Some((hole, math_right, width, _)) = next else {
                        break;
                    };
                    let _ = hole;
                    cursor = *math_right;
                    covered += *width;
                    guard += 1;
                    if guard > 8 {
                        break;
                    }
                }
                assert!(
                    (cursor - gap_end).abs() < 1.5,
                    "line y={y:.1} gap {gap_start:.1}-{gap_end:.1} ({gap:.1}pt) is not the math (reached {cursor:.1}, covered {covered:.1})"
                );
            }
            let mut right = on_line
                .iter()
                .map(|slice| slice.right)
                .fold(column_left, f32::max);
            let left = if indent {
                on_line
                    .iter()
                    .map(|slice| slice.x)
                    .fold(column_right, f32::min)
            } else {
                column_left
            };
            for (hole, math_right, _, _) in &formulas {
                if *hole >= left - 1.0 && *math_right <= right + 80.0 && *hole <= right + 1.0 {
                    right = right.max(*math_right);
                }
            }
            rows.push((*y, left, right));
        }
        assert!(rows.len() >= 3, "paragraph collapsed: {rows:?}");
        assert!(
            rows.last().is_some_and(|row| row.2 - row.1 > 80.0),
            "the paragraph still ends on a short orphan line: {rows:?}"
        );
        for (y, left, right) in rows.iter().take(rows.len() - 1) {
            let available = column_right - left;
            let fill = (right - left) / available;
            assert!(
                fill >= 0.90,
                "line at y={y:.1} fills {fill:.2} ({left:.1}-{right:.1}, edge {column_right:.1})"
            );
        }
    }

    #[test]
    fn the_k_server_page10_hats_stay_in_holes_and_the_paragraph_fills() {
        let path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../corpus/cache/arxiv-2609.15979.pdf");
        if !path.is_file() {
            return;
        }
        let pdf = PdfDocument::open(&path).unwrap();
        let extracted = pdf.extract();
        let segmentation = crate::segment::segment_placed(
            &extracted.glyphs,
            &crate::segment::SegmentFlags::default(),
            &extracted.regions,
            &extracted.pages,
        );
        let merged = merge_stacked_paragraphs(segmentation.segments, &extracted.glyphs);
        let page: Vec<_> = merged
            .iter()
            .filter(|segment| segment.page_index == 9)
            .collect();
        for segment in &merged {
            let letters = segment
                .text
                .chars()
                .filter(|ch| ch.is_ascii_alphabetic())
                .count();
            if letters < 20 {
                continue;
            }
            assert!(
                !segment.text.contains('\u{f8f8}')
                    && !segment.text.contains('■')
                    && !segment.text.contains('\u{FFFD}'),
                "tofu in prose on page {}: {}",
                segment.page_index + 1,
                segment.text.chars().take(96).collect::<String>()
            );
        }
        assert!(
            page.iter().all(|segment| segment.text != "k−1"),
            "the K^{{k-1}} superscript is still its own line"
        );
        let paragraph = page
            .iter()
            .find(|segment| segment.text.contains("Each family spans"))
            .unwrap_or_else(|| panic!("the coordinate-family paragraph is still split"));
        assert!(
            !paragraph.text.contains('\u{f8f8}')
                && !paragraph.text.contains('■')
                && !paragraph.text.contains('\u{FFFD}'),
            "a hat leaked into the prose as tofu: {}",
            paragraph.text
        );
        assert!(
            paragraph.text.contains('⟦'),
            "hatted math was not holed: {}",
            paragraph.text
        );
        let lemma = page
            .iter()
            .find(|segment| segment.text.contains("new potential after the request"))
            .unwrap_or_else(|| panic!("lemma 4.2 statement missing"));
        assert!(
            !lemma.text.contains('\u{f8f8}') && !lemma.text.contains('■'),
            "lemma 4.2 still has a hat stand-in: {}",
            lemma.text
        );
        let by_id = glyph_index(&extracted.glyphs);
        let glyphs: Vec<&Glyph> = paragraph
            .glyph_ids
            .iter()
            .filter_map(|id| extracted.glyphs.get(by_id[id]))
            .collect();
        let translated = "考虑这三个量 ⟦1⟧ 和 ⟦2⟧。定义这些量的行列式的大小分别为 k、⟦3⟧ 1 和 ⟦0⟧ = ⟦4⟧。每个族都张成其坐标空间：H 张成 ⟦5⟧，其投影张成 ⟦6⟧ 以及投影基的乘积张成剩余的二次坐标。因此，这三个量都是有限的。";
        let mut points: Vec<u32> = translated
            .chars()
            .map(|ch| ch as u32)
            .chain("0123456789　 kHΨµμ=，。、以及".chars().map(|ch| ch as u32))
            .collect();
        points.sort_unstable();
        points.dedup();
        let font = subset_for_style(
            FaceStyle {
                serif: true,
                bold: false,
                italic: false,
            },
            &points,
            &FontSources::default(),
        )
        .expect("cjk font");
        let column_right = glyphs
            .iter()
            .filter(|glyph| {
                glyph.font_size > 9.0 && glyph.unicode.chars().any(|ch| ch.is_ascii_alphabetic())
            })
            .map(|glyph| glyph.matrix[4] + glyph.advance[0].max(0.0))
            .fold(0.0f32, f32::max);
        assert!(
            (column_right - 540.0).abs() < 1.5,
            "page 10 column right drifted to {column_right:.1}"
        );
        let mut drawn = layout_segment(
            &glyphs,
            translated,
            &font,
            &extracted,
            false,
            "RPT",
            0.0,
            CjkMeasure::resolve(0.0, 0.0),
        )
        .unwrap_or_else(|| panic!("page 10 family paragraph did not fit"));
        let shifts = lift_stack_placeholders(&mut drawn, &glyphs, &font)
            .unwrap_or_else(|| panic!("a formula hole was missing"));
        assert!(
            shifts.iter().any(|shift| {
                shift.ids.iter().any(|id| {
                    extracted
                        .glyphs
                        .get(by_id[id])
                        .is_some_and(|glyph| glyph.unicode.contains('\u{f8f8}'))
                })
            }),
            "the hat was not painted from the original glyph"
        );
        let painted: String = drawn.iter().map(|line| line.text.as_str()).collect();
        assert!(
            !painted.contains('■')
                && !painted.contains('\u{FFFD}')
                && !painted.contains('\u{f8f8}'),
            "tofu in the family paragraph: {painted}"
        );
        let mut rows: Vec<(f32, f32, f32)> = Vec::new();
        for line in &drawn {
            let right = line.x + line.widths.iter().sum::<f32>() + line.gaps.iter().sum::<f32>();
            assert!(
                right <= column_right + 0.8,
                "text at y={:.1} x={:.1} ends at {right:.1} (widths {:.1} gaps {:.1}), past {column_right:.1}: {}",
                line.y,
                line.x,
                line.widths.iter().sum::<f32>(),
                line.gaps.iter().sum::<f32>(),
                line.text
            );
            if let Some(row) = rows
                .iter_mut()
                .find(|row: &&mut (f32, f32, f32)| (row.0 - line.y).abs() < 0.6)
            {
                row.1 = row.1.min(line.x);
                row.2 = row.2.max(right);
            } else {
                rows.push((line.y, line.x, right));
            }
        }
        rows.sort_by(|left, right| right.0.total_cmp(&left.0));
        for pair in rows.windows(2) {
            let gap = pair[0].0 - pair[1].0;
            assert!(
                gap > 8.0,
                "lines overlap at y={:.1} and {:.1}",
                pair[0].0,
                pair[1].0
            );
        }
        let column_left = 72.0f32;
        for (index, (y, left, right)) in rows.iter().enumerate() {
            if index + 1 == rows.len() {
                assert!(
                    right - left > 40.0,
                    "the paragraph ends on a scrap at y={y:.1}"
                );
                continue;
            }
            let start = if index == 0 { *left } else { column_left };
            let fill = (right - start) / (column_right - start);
            assert!(
                fill >= 0.90,
                "line at y={y:.1} fills {fill:.2} ({start:.1}-{right:.1})"
            );
        }
        let lemma_glyphs: Vec<&Glyph> = lemma
            .glyph_ids
            .iter()
            .filter_map(|id| extracted.glyphs.get(by_id[id]))
            .collect();
        let lemma_text = "请求之后的新势满足 ⟦0⟧ ⟦1⟧ + ⟦2⟧。";
        let mut lemma_points: Vec<u32> = lemma_text
            .chars()
            .map(|ch| ch as u32)
            .chain(points)
            .collect();
        lemma_points.sort_unstable();
        lemma_points.dedup();
        let lemma_font = subset_for_style(
            FaceStyle {
                serif: true,
                bold: false,
                italic: lemma_glyphs
                    .iter()
                    .any(|glyph| glyph.font_name.to_ascii_lowercase().contains("italic")),
            },
            &lemma_points,
            &FontSources::default(),
        )
        .expect("lemma font");
        let mut lemma_drawn = layout_segment(
            &lemma_glyphs,
            lemma_text,
            &lemma_font,
            &extracted,
            false,
            "RPT",
            0.0,
            CjkMeasure::resolve(0.0, 0.0),
        )
        .unwrap_or_else(|| panic!("lemma 4.2 did not fit: {}", lemma.text));
        let lemma_shifts = lift_stack_placeholders(&mut lemma_drawn, &lemma_glyphs, &lemma_font)
            .unwrap_or_else(|| panic!("lemma 4.2 dropped a hole"));
        assert!(
            lemma_shifts.iter().any(|shift| {
                shift.ids.iter().any(|id| {
                    extracted
                        .glyphs
                        .get(by_id[id])
                        .is_some_and(|glyph| glyph.unicode.contains('\u{f8f8}'))
                })
            }),
            "lemma 4.2 hat was not kept"
        );
        let lemma_paint: String = lemma_drawn.iter().map(|line| line.text.as_str()).collect();
        assert!(
            !lemma_paint.contains('■') && !lemma_paint.contains('\u{FFFD}'),
            "tofu in lemma 4.2: {lemma_paint}"
        );
        let mut lemma_ys: Vec<f32> = lemma_drawn.iter().map(|line| line.y).collect();
        lemma_ys.sort_by(|left, right| left.total_cmp(right));
        lemma_ys.dedup_by(|left, right| (*left - *right).abs() < 0.8);
        let lemma_lines: Vec<&str> = lemma_drawn.iter().map(|line| line.text.as_str()).collect();
        assert_eq!(lemma_ys.len(), 1, "lemma 4.2 wrapped: {lemma_lines:?}");
        let plus = lemma_drawn
            .iter()
            .find(|line| line.text.contains('+'))
            .expect("the plus between the two potentials");
        let period = lemma_drawn
            .iter()
            .find(|line| line.text.contains('。'))
            .expect("the period after the formula");
        let mut formula_right = 0.0f32;
        let mut formula_left = f32::MAX;
        for shift in &lemma_shifts {
            for id in &shift.ids {
                let Some(glyph) = extracted.glyphs.get(by_id[id]) else {
                    continue;
                };
                let left = glyph.matrix[4].min(glyph.bbox[0]) + shift.dx;
                let right =
                    glyph.bbox[2].max(glyph.matrix[4] + glyph.advance[0].max(0.0)) + shift.dx;
                formula_left = formula_left.min(left);
                formula_right = formula_right.max(right);
            }
        }
        assert!(
            plus.x + 0.4 >= formula_left && plus.x + 1.0 <= formula_right,
            "the plus at {:.1} is not between the formula ink {:.1}-{:.1}",
            plus.x,
            formula_left,
            formula_right
        );
        assert!(
            period.x + 0.4 >= formula_right,
            "the period at {:.1} landed inside the formula ending at {:.1}",
            period.x,
            formula_right
        );
        assert!(
            lemma_drawn
                .iter()
                .all(|line| line.text.trim() != "ij" && line.text.trim() != "′"),
            "a script fragment was stamped beside the lemma: {lemma_lines:?}"
        );
        for line in &lemma_drawn {
            let right = line.x + line.widths.iter().sum::<f32>() + line.gaps.iter().sum::<f32>();
            assert!(right <= column_right + 0.8, "lemma 4.2 ends at {right:.1}");
        }
        let old = page
            .iter()
            .find(|segment| segment.text.contains("old potential before the request"))
            .unwrap_or_else(|| panic!("lemma 4.1 statement missing"));
        assert!(
            !old.text.contains('\u{f8f8}') && !old.text.contains('■'),
            "lemma 4.1 still has a hat stand-in: {}",
            old.text
        );
        assert!(
            page.iter().any(|segment| {
                segment
                    .text
                    .starts_with("Multiplying a vector ⟦0⟧ ⟦1⟧ by e1")
            }),
            "the e1 paragraph lost its math holes"
        );
        let let_line = page
            .iter()
            .find(|segment| segment.text.contains("bottom coordinate block"))
            .expect("the bottom-block sentence");
        let let_glyphs: Vec<&Glyph> = let_line
            .glyph_ids
            .iter()
            .filter_map(|id| extracted.glyphs.get(by_id[id]))
            .collect();
        assert!(
            !let_line.text.contains("⟧e"),
            "the second e of e_i e_j stayed in the words: {}",
            let_line.text
        );
        let let_text = "设 ⟦0⟧ 是 Q 的底部坐标块，由满足 2 ⟦2⟧ 的行 ⟦1⟧ 组成：";
        let mut let_points: Vec<u32> = let_text
            .chars()
            .map(|ch| ch as u32)
            .chain(lemma_points.iter().copied())
            .collect();
        let_points.sort_unstable();
        let_points.dedup();
        let let_font = subset_for_style(
            FaceStyle {
                serif: true,
                bold: false,
                italic: false,
            },
            &let_points,
            &FontSources::default(),
        )
        .expect("let font");
        let mut let_drawn = layout_segment(
            &let_glyphs,
            let_text,
            &let_font,
            &extracted,
            false,
            "RPT",
            0.0,
            CjkMeasure::resolve(0.0, 0.0),
        )
        .expect("the bottom-block sentence did not fit");
        assert!(
            let_drawn.iter().all(|line| line.text.trim() != "ij"),
            "the e_ij subscript was stamped at the source x: {:?}",
            let_drawn
                .iter()
                .map(|line| line.text.as_str())
                .collect::<Vec<_>>()
        );
        let let_shifts =
            lift_stack_placeholders(&mut let_drawn, &let_glyphs, &let_font).expect("let holes");
        let row_shift = let_shifts.iter().find(|shift| {
            shift.ids.iter().any(|id| {
                extracted
                    .glyphs
                    .get(by_id[id])
                    .is_some_and(|glyph| glyph.unicode == "j" && glyph.font_size < 9.0)
            })
        });
        let row_shift = row_shift.expect("e_i e_j hole");
        let bases: Vec<&Glyph> = row_shift
            .ids
            .iter()
            .filter_map(|id| extracted.glyphs.get(by_id[id]))
            .filter(|glyph| glyph.unicode == "e" && glyph.font_size > 9.0)
            .collect();
        assert_eq!(bases.len(), 2, "e_i e_j kept only one e: {bases:?}");
        assert!(
            let_drawn.iter().all(|line| line.text.trim() != "e"),
            "a stray e was painted beside e_i e_j: {:?}",
            let_drawn
                .iter()
                .map(|line| line.text.as_str())
                .collect::<Vec<_>>()
        );
        let view = page
            .iter()
            .find(|segment| segment.text.contains("View q"))
            .expect("the update sentence");
        let view_glyphs: Vec<&Glyph> = view
            .glyph_ids
            .iter()
            .filter_map(|id| extracted.glyphs.get(by_id[id]))
            .collect();
        let view_text =
            "将 q⟦0⟧ 视为 ⟦1⟧⟦2⟧ 的线性多项式。更新为 ⟦4⟧⟦3⟧ ⟦5⟧ + q⟦6⟧。展开一个新二次列可得";
        let mut view_points: Vec<u32> = view_text
            .chars()
            .map(|ch| ch as u32)
            .chain(let_points)
            .collect();
        view_points.sort_unstable();
        view_points.dedup();
        let view_font = subset_for_style(
            FaceStyle {
                serif: true,
                bold: false,
                italic: false,
            },
            &view_points,
            &FontSources::default(),
        )
        .expect("view font");
        let mut view_drawn = layout_segment(
            &view_glyphs,
            view_text,
            &view_font,
            &extracted,
            false,
            "RPT",
            0.0,
            CjkMeasure::resolve(0.0, 0.0),
        )
        .expect("the update sentence did not fit");
        let view_shifts = lift_stack_placeholders(&mut view_drawn, &view_glyphs, &view_font)
            .expect("the update sentence dropped a hole");
        let q_lines: Vec<&Drawn> = view_drawn
            .iter()
            .filter(|line| line.text.contains('q'))
            .collect();
        assert!(!q_lines.is_empty(), "q was not painted");
        for shift in &view_shifts {
            let members: Vec<&Glyph> = shift
                .ids
                .iter()
                .filter_map(|id| extracted.glyphs.get(by_id[id]))
                .collect();
            let hat = members
                .iter()
                .any(|glyph| glyph.unicode.contains('\u{f8f8}'));
            let letter = members
                .iter()
                .any(|glyph| glyph.unicode.trim() == "q" && glyph.font_size > 9.0);
            if !hat || letter {
                continue;
            }
            let hat_x = members
                .iter()
                .filter(|glyph| glyph.unicode.contains('\u{f8f8}'))
                .map(|glyph| glyph.matrix[4] + shift.dx)
                .fold(f32::MAX, f32::min);
            let on_q = q_lines.iter().any(|line| {
                let chars: Vec<char> = line.text.chars().collect();
                chars.iter().enumerate().any(|(index, ch)| {
                    if *ch != 'q' {
                        return false;
                    }
                    let x = char_origin(line, &chars, index);
                    let width = line.widths.get(index).copied().unwrap_or(line.size);
                    hat_x + 1.0 >= x && hat_x <= x + width + 1.5
                })
            });
            assert!(on_q, "a hat at {hat_x:.1} is detached from q");
        }
        let multiply = page
            .iter()
            .find(|segment| segment.text.starts_with("Multiplying a vector"))
            .expect("multiplying sentence");
        let multiply_glyphs: Vec<&Glyph> = multiply
            .glyph_ids
            .iter()
            .filter_map(|id| extracted.glyphs.get(by_id[id]))
            .collect();
        let multiply_text = "将向量 ⟦0⟧ ⟦1⟧ 乘以 e1 会将其 k 个坐标放入这些行，并在其余每个二次行中放入零。由于 ⟦2⟧ = e1，这些列";
        let mut multiply_points: Vec<u32> = multiply_text
            .chars()
            .map(|ch| ch as u32)
            .chain(view_points)
            .collect();
        multiply_points.sort_unstable();
        multiply_points.dedup();
        let multiply_font = subset_for_style(
            FaceStyle {
                serif: true,
                bold: false,
                italic: false,
            },
            &multiply_points,
            &FontSources::default(),
        )
        .expect("multiply font");
        let multiply_drawn = layout_segment(
            &multiply_glyphs,
            multiply_text,
            &multiply_font,
            &extracted,
            false,
            "RPT",
            0.0,
            CjkMeasure::resolve(0.0, 0.0),
        )
        .expect("the multiplying sentence did not fit");
        let sunk = multiply_drawn.iter().any(|line| {
            line.text.trim() == "1"
                && multiply_drawn.iter().any(|host| {
                    host.text.contains('e')
                        && host.y > line.y + 0.5
                        && (host.y - line.y) < host.size
                })
        });
        assert!(
            sunk,
            "e1 stayed on the baseline: {:?}",
            multiply_drawn
                .iter()
                .map(|line| (line.y, line.text.as_str()))
                .collect::<Vec<_>>()
        );
        let mixed = merged
            .iter()
            .find(|segment| segment.text.contains("For a mixed term"))
            .unwrap_or_else(|| panic!("mixed term missing"));
        let mixed_glyphs: Vec<&Glyph> = mixed
            .glyph_ids
            .iter()
            .filter_map(|id| extracted.glyphs.get(by_id[id]))
            .collect();
        let mixed_text = "对于混合项，使用 π⟦0⟧ ⟦1⟧⟦2⟧ 写出";
        let mut mixed_points: Vec<u32> = mixed_text
            .chars()
            .map(|ch| ch as u32)
            .chain(lemma_points)
            .collect();
        mixed_points.sort_unstable();
        mixed_points.dedup();
        let mixed_font = subset_for_style(
            FaceStyle {
                serif: true,
                bold: false,
                italic: false,
            },
            &mixed_points,
            &FontSources::default(),
        )
        .expect("mixed font");
        let mut mixed_drawn = layout_segment(
            &mixed_glyphs,
            mixed_text,
            &mixed_font,
            &extracted,
            false,
            "RPT",
            0.0,
            CjkMeasure::resolve(0.0, 0.0),
        )
        .unwrap_or_else(|| panic!("mixed term did not fit: {}", mixed.text));
        assert!(
            mixed_drawn.iter().all(|line| line.text != "出"),
            "the last character was stamped onto the formula"
        );
        let mixed_shifts = lift_stack_placeholders(&mut mixed_drawn, &mixed_glyphs, &mixed_font)
            .unwrap_or_else(|| panic!("mixed term dropped a hole"));
        let write = mixed_drawn
            .iter()
            .find(|line| line.text.contains('写'))
            .unwrap_or_else(|| panic!("写出 was not painted"));
        let write_x = write.x;
        for shift in &mixed_shifts {
            let mut right = f32::MIN;
            for id in &shift.ids {
                let Some(glyph) = extracted.glyphs.get(by_id[id]) else {
                    continue;
                };
                let x1 = super::glyph_paint_right(glyph) + shift.dx;
                right = right.max(x1);
            }
            assert!(
                right <= write_x + 0.6,
                "formula ink ends at {right:.1}, inside 写出 at {write_x:.1}"
            );
        }
    }

    #[test]
    fn a_pulled_line_carries_its_formula() {
        let line = Drawn {
            page: 0,
            x: 72.0,
            y: 510.0,
            size: 10.0,
            color: Color::black(),
            cids: vec![1],
            resource: "F1".into(),
            skew: 0.0,
            text: "请求之前的旧势满足".into(),
            glyph_ids: vec![7, 8],
            widths: vec![10.0],
            gaps: Vec::new(),
            supers: vec![false],
            sup_scale: 1.0,
            sup_rise: 0.0,
        };
        let other = Drawn {
            page: 0,
            x: 72.0,
            y: 490.0,
            size: 10.0,
            color: Color::black(),
            cids: vec![2],
            resource: "F1".into(),
            skew: 0.0,
            text: "证明。".into(),
            glyph_ids: vec![9],
            widths: vec![10.0],
            gaps: Vec::new(),
            supers: vec![false],
            sup_scale: 1.0,
            sup_rise: 0.0,
        };
        let drawn = vec![line, other];
        let y_before = vec![492.0, 470.0];
        let mut shifts = vec![ListingShift {
            page: 0,
            ids: vec![7],
            dx: -20.0,
            dy: 4.0,
            host_y: 492.0,
        }];
        carry_formula_with_line(&drawn, &y_before, &mut shifts);
        assert!(
            (shifts[0].dy - 22.0).abs() < 0.01,
            "formula dy {} did not follow the 18pt pull",
            shifts[0].dy
        );
        let mut listing = ListingShift {
            page: 0,
            ids: vec![9],
            dx: 0.0,
            dy: 18.0,
            host_y: f32::NAN,
        };
        carry_formula_with_line(&drawn, &y_before, std::slice::from_mut(&mut listing));
        assert!(
            (listing.dy - 18.0).abs() < 0.01,
            "a listing shift was pulled twice"
        );
    }

    #[test]
    fn a_script_fragment_hole_is_the_overhang_past_its_base() {
        let mut q = ink_glyph(1, 100.0, 200.0, 10.0, "q");
        q.bbox = [100.0, 198.0, 105.0, 208.0];
        q.advance = [8.0, 0.0];
        let mut hat = ink_glyph(2, 101.0, 204.0, 9.0, "\u{f8f8}");
        hat.font_name = "LMMathExtension10".into();
        hat.bbox = [101.0, 202.0, 106.0, 210.0];
        hat.advance = [5.5, 0.0];
        let mut sub = ink_glyph(3, 105.0, 197.0, 7.0, "x");
        sub.font_name = "LMMathItalic8".into();
        sub.bbox = [105.0, 195.0, 109.0, 203.0];
        sub.advance = [6.0, 0.0];
        // A letter on the next line sits under the hat in x. It must not
        // become the base, or the hole keeps the fragment's full width.
        let mut below = ink_glyph(5, 104.0, 186.0, 10.0, "c");
        below.bbox = [104.0, 184.0, 110.0, 194.0];
        below.advance = [6.0, 0.0];
        let glyphs = [q, hat, sub, below];
        let refs: Vec<&Glyph> = glyphs.iter().collect();
        let by_id = super::glyph_index_refs(&refs);
        let width = super::formula_hole_width(&[2, 3], &refs, &by_id, 10.0, Some('q'));
        assert!(
            (width - 4.0).abs() < 0.2,
            "script hole reserved {width:.2}, expected the 4pt overhang past q"
        );
        let full = super::formula_hole_width(&[2, 3], &refs, &by_id, 10.0, None);
        assert!(
            (full - 8.0).abs() < 0.2,
            "a fragment with no base letter reserved {full:.2}, expected the full 8pt ink"
        );
        let mut paren = ink_glyph(4, 200.0, 200.0, 10.0, ")");
        paren.bbox = [200.0, 198.0, 204.0, 208.0];
        paren.advance = [8.0, 0.0];
        let plain = [paren];
        let plain_refs: Vec<&Glyph> = plain.iter().collect();
        let plain_ids = super::glyph_index_refs(&plain_refs);
        let plain_width = super::formula_hole_width(&[4], &plain_refs, &plain_ids, 10.0, None);
        assert!(
            (plain_width - 4.0).abs() < 0.2,
            "trailing advance was reserved as hole padding: {plain_width:.2}"
        );
    }

