    #[test]
    fn an_echoed_english_body_fails_when_other_prose_was_translated() {
        let bytes = prose_pdf();
        let mut doc = PdfDocument::open_bytes(&bytes).unwrap();
        let mut extraction = doc.extract();
        let report = prose_report(&extraction, true);
        let font = box_ttf(&[b'A' as u32, b'B' as u32]);
        doc.rewrite(
            &mut extraction,
            &report,
            &RewriteOptions {
                font_bytes: Some(font),
                ..RewriteOptions::default()
            },
        )
        .unwrap();
        let coverage = extraction.coverage_report();
        assert!(!coverage.complete, "{coverage:?}");
        assert!(coverage.english_body > 0, "{coverage:?}");
        let echoed = extraction.glyphs.iter().any(|glyph| {
            glyph.unicode == "T"
                && matches!(
                    &glyph.disposition,
                    Disposition::KeptOriginal { reason } if reason == "english-body"
                )
        });
        assert!(echoed, "the body paragraph should be flagged english-body");
        let proper = extraction
            .glyphs
            .iter()
            .find(|glyph| glyph.unicode == "G")
            .expect("RAG");
        assert!(
            matches!(&proper.disposition, Disposition::KeptOriginal { reason } if reason == "unchanged"),
            "a short proper noun stays unchanged: {:?}",
            proper.disposition
        );
    }

    #[test]
    fn an_identity_echo_of_english_prose_stays_complete() {
        let bytes = prose_pdf();
        let mut doc = PdfDocument::open_bytes(&bytes).unwrap();
        let mut extraction = doc.extract();
        let report = prose_report(&extraction, false);
        let font = box_ttf(&[b'A' as u32, b'B' as u32]);
        doc.rewrite(
            &mut extraction,
            &report,
            &RewriteOptions {
                font_bytes: Some(font),
                ..RewriteOptions::default()
            },
        )
        .unwrap();
        assert!(
            extraction.assert_complete().is_ok(),
            "{:?}",
            extraction.coverage_report()
        );
        assert!(extraction.glyphs.iter().all(|glyph| {
            !matches!(
                &glyph.disposition,
                Disposition::KeptOriginal { reason } if reason == "english-body"
            )
        }));
    }

    #[test]
    fn a_citation_stays_on_the_line_with_the_following_cjk() {
        let text = "见(Rashid et al.,2025)上评估AutoCompact分别取得通过率";
        let mut glyphs = HashMap::new();
        for (id, ch) in (1u16..).zip(text.chars()) {
            glyphs.insert(ch as u32, (id, 1000));
        }
        let font = SubsetFont {
            bytes: Vec::new(),
            units_per_em: 1000,
            glyphs,

            fallback: None,
            notice: None,
        };
        // 22em ends at "上". The old wrapper jumped back to the space in "et al.".
        let lines = wrap_text(text, 10.0, 220.0, 220.0, &font).unwrap();
        assert!(
            lines[0].contains("et al.,2025)") && lines[0].ends_with('上'),
            "{lines:?}"
        );
        let gaps = justify_gaps(lines[0].as_str(), 10.0, 400.0, &font, true);
        assert!(
            gaps.iter().all(|gap| *gap == 0.0),
            "a short citation line must not be letter-spaced: {gaps:?}"
        );
        let cjk = "中文正文需要两端对齐";
        let mut cjk_glyphs = HashMap::new();
        for (id, ch) in (1u16..).zip(cjk.chars()) {
            cjk_glyphs.insert(ch as u32, (id, 1000));
        }
        let cjk_font = SubsetFont {
            bytes: Vec::new(),
            units_per_em: 1000,
            glyphs: cjk_glyphs,

            fallback: None,
            notice: None,
        };
        let count = cjk.chars().count();
        let width = count as f32 * 10.0 + 2.0;
        let cjk_gaps = justify_gaps(cjk, 10.0, width, &cjk_font, true);
        assert!(
            cjk_gaps.iter().all(|gap| *gap > 0.0),
            "pure CJK slack should spread across every ideograph gap: {cjk_gaps:?}"
        );
        let mixed = "中文(Rashid)后续";
        let mut mixed_glyphs = HashMap::new();
        for (id, ch) in (1u16..).zip(mixed.chars()) {
            mixed_glyphs.insert(ch as u32, (id, 1000));
        }
        let mixed_font = SubsetFont {
            bytes: Vec::new(),
            units_per_em: 1000,
            glyphs: mixed_glyphs,

            fallback: None,
            notice: None,
        };
        let mixed_width = measure(mixed, 10.0, &mixed_font) + 0.6;
        let mixed_gaps = justify_gaps(mixed, 10.0, mixed_width, &mixed_font, true);
        let chars: Vec<char> = mixed.chars().collect();
        for (index, gap) in mixed_gaps.iter().enumerate() {
            let latin = !is_cjk_body(chars[index]) || !is_cjk_body(chars[index + 1]);
            if latin {
                assert_eq!(*gap, 0.0, "gap {index} in {mixed}");
            }
        }
        assert!(mixed_gaps.iter().any(|gap| *gap > 0.0), "{mixed_gaps:?}");
    }

    #[test]
    fn latin_words_are_not_split_across_lines() {
        let mut glyphs = HashMap::new();
        for (id, ch) in (1u16..).zip("包括SelfCompact、SWE-Compressor和变体".chars()) {
            glyphs.insert(ch as u32, (id, 1000));
        }
        let font = SubsetFont {
            bytes: Vec::new(),
            units_per_em: 1000,
            glyphs,

            fallback: None,
            notice: None,
        };
        // 14em fits "包括SelfCompact、" (14 chars) but not the following name.
        let lines = wrap_text(
            "包括SelfCompact、SWE-Compressor和变体",
            10.0,
            145.0,
            145.0,
            &font,
        )
        .unwrap();
        assert!(
            lines.iter().any(|line| line.contains("SWE-Compressor")),
            "{lines:?}"
        );
        assert!(
            !lines
                .iter()
                .any(|line| line.contains("SWE-") && !line.contains("Compressor")),
            "{lines:?}"
        );
    }

    #[test]
    fn an_unhit_mark_on_the_next_page_stays_on_that_page() {
        let font = uniform_font("中3");
        let mut home = math_glyph(0, 80.0, 500.0, "A", false);
        home.page_index = 0;
        let mut mark = math_glyph(1, 80.0, 200.0, "3", false);
        mark.page_index = 1;
        mark.bbox = [80.0, 200.0, 86.0, 210.0];
        let mut drawn = vec![Drawn {
            page: 0,
            x: 80.0,
            y: 500.0,
            size: 10.0,
            color: Color::black(),
            cids: vec![],
            resource: "RPT0".into(),
            skew: 0.0,
            text: "中".into(),
            glyph_ids: vec![0],
            widths: vec![10.0],
            gaps: vec![],
            supers: vec![],
            sup_scale: 1.0,
            sup_rise: 0.0,
        }];
        let glyphs = [&home, &mark];
        cover_unhit_clusters(
            &mut drawn,
            &glyphs,
            &font,
            "RPT0",
            0.0,
            &Color::black(),
            &[0, 1],
            &[],
        );
        let marks: Vec<_> = drawn
            .iter()
            .filter(|line| line.text.contains('3'))
            .map(|line| line.page)
            .collect();
        assert_eq!(marks, vec![1], "{marks:?}");
    }

    fn uniform_font(text: &str) -> SubsetFont {
        let mut glyphs = HashMap::new();
        for (id, ch) in (1u16..).zip(text.chars()) {
            glyphs.insert(ch as u32, (id, 1000));
        }
        SubsetFont {
            bytes: Vec::new(),
            units_per_em: 1000,
            glyphs,
            fallback: None,
            notice: None,
        }
    }

    #[test]
    fn a_centered_title_may_use_the_page_measure() {
        let media = [0.0, 0.0, 595.0, 842.0];
        let (left, right) = centered_heading_span(HeadingLevel::Title, 14.35, media, 180.0, 416.0)
            .expect("centered title");
        assert!(right - left > 400.0, "{left}..{right}");
        assert!(
            centered_heading_span(HeadingLevel::Title, 14.35, media, 88.0, 274.0).is_none(),
            "a left column is not a page-centered title"
        );
        assert!(
            centered_heading_span(HeadingLevel::Body, 14.35, media, 180.0, 416.0).is_none(),
            "body text keeps the ink box"
        );
    }

    #[test]
    fn a_shorter_centered_title_stays_on_the_source_axis() {
        let title = "深度残差学习用于图像识别";
        let body = "我们提出残差学习框架";
        let mut points: Vec<u32> = title
            .chars()
            .chain(body.chars())
            .map(|ch| ch as u32)
            .collect();
        points.sort_unstable();
        points.dedup();
        let Some(font) = subset_for_style(
            FaceStyle {
                serif: true,
                bold: false,
                italic: false,
            },
            &points,
            &FontSources::default(),
        ) else {
            return;
        };
        let page = |glyphs: Vec<Glyph>| Extraction {
            coordinate_space: "user",
            pages: vec![crate::glyph::PageInfo {
                index: 0,
                object_id: "1 0".into(),
                media_box: [0.0, 0.0, 612.0, 792.0],
                rotate: 0,
            }],
            glyphs,
            regions: Vec::new(),
            diagnostics: Vec::new(),
        };
        let band = |id: u32, x: f32, right: f32, y: f32, size: f32, text: &str| {
            let mut glyph = ink_glyph(id, x, y, size, text);
            glyph.bbox = [x, y - size * 0.2, right, y + size * 0.8];
            glyph
        };
        let draw = |glyphs: Vec<Glyph>, text: &str| {
            let refs: Vec<&Glyph> = glyphs.iter().collect();
            let extraction = page(glyphs.clone());
            layout_segment(
                &refs,
                text,
                &font,
                &extraction,
                false,
                "RPT",
                0.0,
                CjkMeasure::resolve(0.90, 1.60),
            )
        };
        // ResNet's title is one centered line. Chinese is shorter, so leaving
        // it on the English left edge (or on a tick-label right edge) walks
        // off the page center.
        let title_glyphs = vec![band(
            0,
            153.4,
            441.8,
            680.0,
            14.3,
            "Deep Residual Learning for Image Recognition",
        )];
        let drawn = draw(title_glyphs, title).expect("title fits");
        assert_eq!(
            drawn.len(),
            1,
            "{:?}",
            drawn.iter().map(|line| &line.text).collect::<Vec<_>>()
        );
        let advance = drawn[0].widths.iter().sum::<f32>();
        let mid = drawn[0].x + advance * 0.5;
        assert!(
            (mid - 297.6).abs() < 4.0,
            "title mid {mid:.1} x {:.1} advance {advance:.1}",
            drawn[0].x
        );
        // A column line keeps the left edge.
        let body_glyphs = vec![band(
            0,
            50.0,
            286.0,
            400.0,
            10.0,
            "present a residual learning framework to ease the training",
        )];
        let drawn = draw(body_glyphs, body).expect("body fits");
        assert!(
            drawn[0].x < 70.0,
            "body slid to x {:.1}: {}",
            drawn[0].x,
            drawn[0].text
        );
        // Two full lines of a centered header share both edges. A shorter
        // translation still belongs on that axis, not on the English left.
        let header = vec![
            band(
                0,
                124.0,
                488.0,
                500.0,
                10.0,
                "Provided proper attribution is provided, Google hereby grants",
            ),
            band(
                1,
                124.3,
                487.9,
                486.0,
                10.0,
                "reproduce the tables and figures in this paper solely for use",
            ),
        ];
        let drawn = draw(header, title).expect("header fits");
        for line in &drawn {
            let advance = line.widths.iter().sum::<f32>();
            let mid = line.x + advance * 0.5;
            assert!(
                (mid - 306.0).abs() < 8.0,
                "header mid {mid:.1} x {:.1}: {}",
                line.x,
                line.text
            );
        }
        // BERT's title is two centered lines of different widths.
        let bert = vec![
            band(
                0,
                116.5,
                481.0,
                740.0,
                14.0,
                "BERT: Pre-training of Deep Bidirectional Transformers for",
            ),
            band(1, 220.9, 376.7, 724.0, 14.0, "Language Understanding"),
        ];
        let drawn = draw(bert, title).expect("bert title fits");
        for line in &drawn {
            let advance = line.widths.iter().sum::<f32>();
            let mid = line.x + advance * 0.5;
            assert!(
                (mid - 298.8).abs() < 6.0,
                "line mid {mid:.1} x {:.1}: {}",
                line.x,
                line.text
            );
        }
    }

    #[test]
    fn a_centered_notice_reflows_as_one_balanced_paragraph() {
        let notice = "若提供适当的署名，Google特此授予许可，以复制本文中的表格和图形，仅用于新闻或学术著作。";
        let mut points: Vec<u32> = notice.chars().map(|ch| ch as u32).collect();
        points.sort_unstable();
        points.dedup();
        let Some(font) = subset_for_style(
            FaceStyle {
                serif: true,
                bold: false,
                italic: false,
            },
            &points,
            &FontSources::default(),
        ) else {
            return;
        };
        let page = |glyphs: Vec<Glyph>| Extraction {
            coordinate_space: "user",
            pages: vec![crate::glyph::PageInfo {
                index: 0,
                object_id: "1 0".into(),
                media_box: [0.0, 0.0, 612.0, 792.0],
                rotate: 0,
            }],
            glyphs,
            regions: Vec::new(),
            diagnostics: Vec::new(),
        };
        let band = |id: u32, x: f32, right: f32, y: f32, text: &str| {
            let mut glyph = ink_glyph(id, x, y, 12.0, text);
            glyph.bbox = [x, y - 2.0, right, y + 10.0];
            glyph
        };
        let glyphs = vec![
            band(
                0,
                124.7,
                487.3,
                710.0,
                "Provided proper attribution is provided, Google hereby grants permission to",
            ),
            band(
                1,
                124.3,
                487.9,
                696.0,
                "reproduce the tables and figures in this paper solely for use in journalistic or",
            ),
            band(2, 267.6, 346.5, 682.0, "scholarly works."),
        ];
        let refs: Vec<&Glyph> = glyphs.iter().collect();
        let extraction = page(glyphs.clone());
        let drawn = layout_segment(
            &refs,
            notice,
            &font,
            &extraction,
            false,
            "RPT",
            0.0,
            CjkMeasure::resolve(0.90, 1.60),
        )
        .expect("notice fits");
        let texts: Vec<_> = drawn.iter().map(|line| line.text.as_str()).collect();
        assert!(
            texts.len() >= 2,
            "the notice should wrap across the block: {texts:?}"
        );
        assert!(
            texts
                .iter()
                .all(|line| *line != "学术著作。" && *line != "仅用于新闻或"),
            "source breaks survived: {texts:?}"
        );
        assert!(
            texts.iter().any(|line| line.contains("学术著作")),
            "{texts:?}"
        );
        let mut advances = Vec::new();
        for line in &drawn {
            let advance = line.widths.iter().sum::<f32>();
            advances.push(advance);
            let mid = line.x + advance * 0.5;
            assert!(
                (mid - 306.0).abs() < 8.0,
                "notice mid {mid:.1} x {:.1}: {}",
                line.x,
                line.text
            );
        }
        let longest = advances.iter().copied().fold(0.0f32, f32::max);
        let shortest = advances.iter().copied().fold(f32::MAX, f32::min);
        assert!(
            shortest >= longest * 0.62,
            "unbalanced {advances:?} {texts:?}"
        );
    }

    #[test]
    fn an_author_column_is_one_face_and_one_axis() {
        let name = ink_glyph(1, 133.0, 549.0, 10.0, "Ashish Vaswani");
        let mut name = name;
        name.bbox = [133.0, 547.0, 200.0, 557.0];
        let mut affiliation = ink_glyph(2, 139.0, 538.0, 10.0, "Google Brain");
        affiliation.bbox = [139.0, 536.0, 193.0, 546.0];
        affiliation.font_name = "Times-Roman".into();
        let mut email = ink_glyph(3, 117.0, 527.0, 10.0, "avaswani@google.com");
        email.bbox = [117.0, 525.0, 216.0, 535.0];
        email.font_name = "Courier".into();
        let glyphs = vec![name, affiliation, email];
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![crate::glyph::PageInfo {
                index: 0,
                object_id: "1 0".into(),
                media_box: [0.0, 0.0, 612.0, 792.0],
                rotate: 0,
            }],
            glyphs,
            regions: Vec::new(),
            diagnostics: Vec::new(),
        };
        let font = uniform_font("阿希什·瓦斯瓦尼Google Brainavaswani@google.com");
        let mut drawn = vec![Drawn {
            page: 0,
            x: 133.0,
            y: 549.0,
            size: 10.0,
            color: Color::black(),
            cids: cids_of("阿希什·瓦斯瓦尼", &font),
            resource: "RPT".into(),
            skew: 0.0,
            widths: char_widths("阿希什·瓦斯瓦尼", 10.0, &font),
            gaps: vec![0.0; "阿希什·瓦斯瓦尼".chars().count() - 1],
            text: "阿希什·瓦斯瓦尼".into(),
            supers: Vec::new(),
            sup_scale: 1.0,
            sup_rise: 0.0,
            glyph_ids: vec![1],
        }];
        let mut succeeded = HashSet::from([1]);
        let mut keep = HashMap::from([(2, "name".into()), (3, "unchanged".into())]);
        super::seat_author_columns(
            &mut drawn,
            &mut succeeded,
            &mut keep,
            &extraction,
            &[("RPT".into(), font)],
        );
        assert!(
            succeeded.contains(&2) && succeeded.contains(&3),
            "{succeeded:?}"
        );
        assert!(!keep.contains_key(&2) && !keep.contains_key(&3));
        let texts: Vec<_> = drawn.iter().map(|line| line.text.as_str()).collect();
        assert!(texts.contains(&"Google Brain"), "{texts:?}");
        assert!(texts.contains(&"avaswani@google.com"), "{texts:?}");
        let axis = drawn
            .iter()
            .map(|line| {
                let advance = line.widths.iter().sum::<f32>();
                line.x + advance * 0.5
            })
            .collect::<Vec<_>>();
        let anchor = axis[0];
        assert!(
            axis.iter().all(|mid| (mid - anchor).abs() < 1.0),
            "column drifted {axis:?} {texts:?}"
        );
    }

