    #[test]
    fn a_copied_author_star_is_not_stamped_at_the_source_x() {
        let name = "诺姆·沙泽尔*";
        let font = uniform_font(&format!("{name}Q"));
        let widths = char_widths(name, 9.0, &font);
        let mut drawn = vec![Drawn {
            page: 0,
            x: 200.0,
            y: 549.3,
            size: 9.0,
            color: Color::black(),
            cids: cids_of(name, &font),
            resource: "RPT".into(),
            skew: 0.0,
            widths,
            gaps: vec![0.0; name.chars().count() - 1],
            text: name.into(),
            supers: Vec::new(),
            sup_scale: 1.0,
            sup_rise: 0.0,
            glyph_ids: vec![1, 2],
        }];
        let mut letters = ink_glyph(1, 244.0, 549.3, 10.0, "Noam");
        letters.bbox = [244.0, 547.0, 290.0, 557.0];
        let mut star = ink_glyph(2, 300.76, 552.92, 6.97, "∗");
        star.bbox = [300.76, 551.5, 304.1, 558.5];
        star.font_name = "CMSY7".into();
        // A letter the translation dropped still has to be stamped. The
        // author star must not, because the name line already ends with one.
        let mut dropped = ink_glyph(3, 420.0, 560.0, 10.0, "Q");
        dropped.bbox = [420.0, 558.0, 428.0, 568.0];
        let glyphs = [&letters, &star, &dropped];
        super::cover_unhit_clusters(
            &mut drawn,
            &glyphs,
            &font,
            "RPT",
            0.0,
            &Color::black(),
            &[1, 2, 3],
            &[],
        );
        assert!(
            !drawn.iter().any(|line| (line.x - 300.76).abs() < 0.5),
            "source star stamped: {:?}",
            drawn
                .iter()
                .map(|line| (line.x, line.y, line.text.as_str()))
                .collect::<Vec<_>>()
        );
        assert_eq!(
            drawn
                .iter()
                .filter(|line| line.text.contains('*') || line.text.contains('∗'))
                .count(),
            1,
            "one star, on the name"
        );
        assert!(
            drawn
                .iter()
                .any(|line| line.text == "Q" && (line.x - 420.0).abs() < 0.5),
            "a dropped letter is still covered"
        );
    }

    #[test]
    fn author_marks_hang_after_the_name() {
        let mut name = ink_glyph(1, 248.0, 499.3, 10.0, "Aidan N. Gomez");
        name.bbox = [248.0, 497.0, 319.3, 507.0];
        name.advance = [71.3, 0.0];
        let mut star = ink_glyph(2, 319.33, 502.92, 7.0, "∗");
        star.bbox = [319.33, 502.0, 323.4, 509.0];
        star.font_name = "CMSY7".into();
        star.font_size = 7.0;
        star = spanned(star, 100, 110);
        let mut dagger = ink_glyph(3, 326.64, 502.92, 7.0, "†");
        dagger.bbox = [326.64, 502.0, 330.3, 509.0];
        dagger.font_name = "CMSY7".into();
        dagger.font_size = 7.0;
        dagger = spanned(dagger, 100, 110);
        let mut note = ink_glyph(
            4,
            108.0,
            120.0,
            9.0,
            "†Work performed while at Google Brain.",
        );
        note.bbox = [108.0, 112.0, 320.0, 128.0];
        note = spanned(note, 200, 220);
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![crate::glyph::PageInfo {
                index: 0,
                object_id: "1 0".into(),
                media_box: [0.0, 0.0, 612.0, 792.0],
                rotate: 0,
            }],
            glyphs: vec![name, star, dagger, note],
            regions: Vec::new(),
            diagnostics: Vec::new(),
        };
        // The CJK face has `*` and not U+2217. The mark still has to hang.
        let font = uniform_font("Aidan N. Gomez*†Work performed while at Google Brain.");
        let name_text = "Aidan N. Gomez";
        let widths = char_widths(name_text, 10.0, &font);
        let mut drawn = vec![Drawn {
            page: 0,
            x: 248.4,
            y: 499.3,
            size: 10.0,
            color: Color::black(),
            cids: cids_of(name_text, &font),
            resource: "RPT".into(),
            skew: 0.0,
            widths: widths.clone(),
            gaps: vec![0.0; name_text.chars().count() - 1],
            text: name_text.into(),
            supers: Vec::new(),
            sup_scale: 1.0,
            sup_rise: 0.0,
            glyph_ids: vec![1],
        }];
        let mut succeeded = HashSet::from([1]);
        let mut keep = HashMap::from([(2, "unchanged".into()), (3, "unchanged".into())]);
        let by_id = glyph_index(&extraction.glyphs);
        super::hang_kept_author_marks(
            &mut drawn,
            &mut succeeded,
            &mut keep,
            &extraction,
            &by_id,
            &[("RPT".into(), font)],
        );
        assert!(
            succeeded.contains(&2) && succeeded.contains(&3),
            "{succeeded:?}"
        );
        assert!(!keep.contains_key(&2) && !keep.contains_key(&3));
        let line = &drawn[0];
        assert_eq!(line.text, "Aidan N. Gomez*†");
        let chars: Vec<char> = line.text.chars().collect();
        let star_at = chars.iter().position(|ch| *ch == '*').expect("star");
        let dagger_at = chars.iter().position(|ch| *ch == '†').expect("dagger");
        assert!(line.supers[star_at] && line.supers[dagger_at]);
        assert!(line.supers[..star_at].iter().all(|flag| !flag));
        let mut cursor = line.x;
        let mut star_x = 0.0;
        let mut dagger_x = 0.0;
        for (index, width) in line.widths.iter().enumerate() {
            if index == star_at {
                star_x = cursor;
            }
            if index == dagger_at {
                dagger_x = cursor;
            }
            cursor += width;
            if index + 1 < line.widths.len() {
                cursor += line.gaps.get(index).copied().unwrap_or(0.0);
            }
        }
        let name_right = line.x + widths.iter().sum::<f32>();
        assert!(
            star_x + 0.2 >= name_right,
            "star {star_x:.2} overlaps the name ending {name_right:.2}"
        );
        assert!(
            dagger_x >= star_x + line.widths[star_at] - 0.05,
            "dagger {dagger_x:.2} overlaps star at {star_x:.2} width {:.2}",
            line.widths[star_at]
        );
        assert!(
            (dagger_x - star_x - 7.3).abs() < 1.2,
            "marks lost the source step, dx {:.2}",
            dagger_x - star_x
        );
    }

    #[test]
    fn chinese_body_is_smaller_with_more_open_leading() {
        let metrics = CjkMeasure::resolve(0.90, 1.60);
        assert!((metrics.body_scale - 0.90).abs() < 1e-4);
        assert!((metrics.leading_ratio - 1.60).abs() < 1e-4);
        assert!(metrics.min_leading_ratio >= 1.40);
        assert!(metrics.heading_scale > metrics.body_scale && metrics.heading_scale <= 1.0);

        let text = "中文正文应当使用更小的字号并且配上更舒适的行距才像论文";
        let font = uniform_font(text);
        // 22 ideographs. At 9pt a 90pt column holds 10, so this is three lines.
        // Two English gaps of 20pt each leave room for a 1.6em Chinese leading.
        let (lines, size, leading, _) = fit_cjk_block(
            text,
            10.0,
            metrics.body_scale,
            90.0,
            0.0,
            40.0,
            &font,
            metrics,
        )
        .unwrap();
        assert_eq!(lines.len(), 3, "{lines:?}");
        assert!(
            (size - 9.0).abs() < 0.05,
            "body should start at 90% of 10pt, got {size}"
        );
        assert!(
            (leading / size - 1.60).abs() < 0.02,
            "leading {leading} / size {size}"
        );

        let (tight_lines, tight_size, tight_leading, _) = fit_cjk_block(
            text,
            10.0,
            metrics.body_scale,
            90.0,
            0.0,
            22.0,
            &font,
            metrics,
        )
        .unwrap();
        assert!(tight_lines.len() >= 2, "{tight_lines:?}");
        // A source gap of at least 1.15em keeps the body size so a short
        // paragraph matches its neighbors. The leading may sit under the
        // 1.40 floor; shrinking the face to restore that floor is the smaller
        // `ε = 10` paragraph this case used to produce.
        assert!(
            (tight_size - size).abs() < 0.05,
            "body size stays when the source gap is at least 1.15em: {tight_size}"
        );
        assert!(
            tight_leading / tight_size + 0.02 >= 1.15,
            "leading {tight_leading} size {tight_size}"
        );

        let title = "论文标题";
        let title_font = uniform_font(title);
        let (_, title_size, _, _) = fit_cjk_block(
            title,
            16.0,
            metrics.heading_scale,
            200.0,
            0.0,
            0.0,
            &title_font,
            metrics,
        )
        .unwrap();
        assert!(
            (title_size - 16.0 * metrics.heading_scale).abs() < 0.05,
            "{title_size}"
        );

        let author = "作者甲";
        let author_font = uniform_font(author);
        let (_, author_size, _, _) = fit_cjk_block(
            author,
            10.0,
            metrics.body_scale,
            200.0,
            0.0,
            0.0,
            &author_font,
            metrics,
        )
        .unwrap();
        assert!((author_size - 9.0).abs() < 0.05, "{author_size}");
    }

    #[test]
    fn body_paragraphs_indent_two_characters_and_headings_do_not() {
        let body = "编程智能体通过长轨迹解决仓库级任务。随着任务推进，早期探索会过时。";
        assert_eq!(cjk_indent_ems(5, 10.0, false, body), 2.0);
        assert_eq!(
            cjk_indent_ems(
                1,
                10.0,
                false,
                "这是单独成段的一句完整正文，句末有句号，所以仍然应当首行缩进。",
            ),
            2.0
        );
        assert_eq!(cjk_indent_ems(1, 14.0, true, "1 引言"), 0.0);
        assert_eq!(cjk_indent_ems(1, 11.0, true, "实验设置"), 0.0);
        assert_eq!(
            cjk_indent_ems(2, 16.0, false, "AutoCompact: 学习何时压缩"),
            0.0
        );
        assert_eq!(cjk_indent_ems(3, 9.0, false, "图1：压缩流程示意"), 0.0);
        assert_eq!(
            cjk_indent_ems(1, 10.0, false, "{xuanzhang826, ltzheng01}@gmail.com"),
            0.0
        );
        assert_eq!(
            cjk_indent_ems(
                1,
                10.0,
                false,
                "■ 您知道如何创建 Python Jupyter Notebook 环境。",
            ),
            0.0
        );

        let font = uniform_font(body);
        let metrics = CjkMeasure::resolve(0.90, 1.60);
        let (lines, size, _, indent) = fit_cjk_block(
            body,
            10.0,
            metrics.body_scale,
            180.0,
            2.0,
            80.0,
            &font,
            metrics,
        )
        .unwrap();
        assert!((indent - size * 2.0).abs() < 0.05, "{indent} {size}");
        assert!(lines.len() >= 2, "{lines:?}");
        let first = measure(lines[0].as_str(), size, &font);
        let second = measure(lines[1].as_str(), size, &font);
        assert!(
            first + indent <= 180.0 + 1.0,
            "first line {first} plus indent {indent}"
        );
        assert!(
            first + size < second || first <= 180.0 - indent,
            "the first line should be the narrower one: {lines:?}"
        );
    }

    #[test]
    fn citations_and_emails_are_not_split_or_letter_spaced() {
        let text = "前文(Jimenez et al., 2024)后文继续";
        let font = uniform_font(text);
        let lines = wrap_text(text, 10.0, 220.0, 220.0, &font).unwrap();
        assert_eq!(lines[0], "前文", "{lines:?}");
        assert!(lines[1].starts_with("(Jimenez et al., 2024)"), "{lines:?}");
        let email = "联系{xuanzhang826, ltzheng01}@gmail.com谢谢";
        let email_font = uniform_font(email);
        let email_lines = wrap_text(email, 10.0, 200.0, 360.0, &email_font).unwrap();
        assert!(
            email_lines
                .iter()
                .any(|line| line.contains("{xuanzhang826, ltzheng01}@gmail.com")),
            "{email_lines:?}"
        );
        assert!(
            !email_lines
                .iter()
                .any(|line| line.contains('@') && !line.contains("gmail.com")),
            "{email_lines:?}"
        );

        let hung = "中文正文。后续";
        let hung_font = uniform_font(hung);
        let hung_lines = wrap_text(hung, 10.0, 45.0, 45.0, &hung_font).unwrap();
        assert_eq!(hung_lines[0], "中文正文。", "{hung_lines:?}");

        let cited = "评估(Rashid et al.,2025)结果很好";
        let cited_font = uniform_font(cited);
        let cited_width = measure(cited, 10.0, &cited_font) + 1.5;
        let cited_gaps = justify_gaps(cited, 10.0, cited_width, &cited_font, true);
        assert!(
            cited_gaps.iter().all(|gap| *gap == 0.0),
            "a citation line stays tight: {cited_gaps:?}"
        );
        let addr = "邮箱user@lab.org谢谢";
        let addr_font = uniform_font(addr);
        let addr_width = measure(addr, 10.0, &addr_font) + 1.5;
        let addr_gaps = justify_gaps(addr, 10.0, addr_width, &addr_font, true);
        assert!(
            addr_gaps.iter().all(|gap| *gap == 0.0),
            "an email line stays tight: {addr_gaps:?}"
        );
    }

    #[test]
    fn a_changed_line_is_drawn_in_a_cjk_face() {
        if !std::path::Path::new("/usr/share/fonts/opentype/noto/NotoSerifCJK-Regular.ttc")
            .is_file()
        {
            return;
        }
        let bytes = sample_pdf();
        let mut doc = PdfDocument::open_bytes(&bytes).unwrap();
        let mut extraction = doc.extract();
        struct ToChinese;
        impl Translator for ToChinese {
            fn complete(&self, _system: &str, user: &str) -> Result<String> {
                let payload: serde_json::Value = serde_json::from_str(user).unwrap();
                let translations: Vec<serde_json::Value> = payload["segments"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|seg| {
                        let text = seg["text"].as_str().unwrap_or("");
                        let translated = if text.contains("Hello") {
                            "你好"
                        } else {
                            text
                        };
                        serde_json::json!({"id": seg["id"], "text": translated})
                    })
                    .collect();
                Ok(serde_json::json!({"translations": translations}).to_string())
            }
        }
        let report =
            translate_extraction(&mut extraction, &TranslateOptions::default(), &ToChinese)
                .unwrap();
        doc.rewrite(&mut extraction, &report, &RewriteOptions::default())
            .unwrap();
        let saved = doc.save_bytes().unwrap();
        let text = PdfDocument::open_bytes(&saved)
            .unwrap()
            .extract()
            .plain_text();
        let squashed: String = text.chars().filter(|ch| !ch.is_whitespace()).collect();
        assert!(squashed.contains("你好"), "{text}");
        assert!(text.contains("References"), "{text}");
        assert!(
            text.lines().any(|line| line.contains("你好")),
            "CJK replacement should stay on one line: {text}"
        );
        let font_program = embedded_cff(&saved).expect("CIDFontType0C font program");
        assert_ne!(&font_program[0..4], b"OTTO", "FontFile3 must be bare CFF");
        assert_eq!(font_program[0], 1, "CFF major version");
        assert_painted_nihao(&saved);
    }

    #[test]
    fn viewers_paint_aeo0_and_cjk() {
        // The source line is wide enough that the probe is not rejected as
        // an overflow. a/e/o/0 are the Standard Encoding slots Noto used as CIDs.
        let bytes = contents_pdf(
            b"BT /F1 12 Tf 1 0 0 1 36 700 Tm (Hello world this line is long enough for the probe text.) Tj ET",
        );
        let saved = paint_system_cjk(&bytes, &[(0, "aeo0中文Transformer2018".into())]);
        let painted = PdfDocument::open_bytes(&saved)
            .unwrap()
            .extract()
            .plain_text();
        assert!(
            painted.contains("aeo0"),
            "translation was not written: {painted}"
        );
        let mut names = Vec::new();
        let loaded = Document::load_mem(&saved).unwrap();
        for object in loaded.objects.values() {
            let Ok(dict) = object.as_dict() else {
                continue;
            };
            let Ok(subtype) = dict.get(b"Subtype").and_then(|obj| obj.as_name()) else {
                continue;
            };
            if subtype != b"Type0" {
                continue;
            }
            let Ok(name) = dict.get(b"BaseFont").and_then(|obj| obj.as_name()) else {
                continue;
            };
            names.push(String::from_utf8_lossy(name).into_owned());
        }
        assert!(
            !names.is_empty(),
            "no Type0 font in {} objects",
            loaded.objects.len()
        );
        assert!(
            names.iter().all(|name| name.starts_with("RPTCJK-")),
            "shared BaseFont: {names:?}"
        );
        let mut unique = names.clone();
        unique.sort();
        unique.dedup();
        assert_eq!(unique.len(), names.len(), "duplicate BaseFont: {names:?}");
        let needle = "aeo0中文Transformer2018";
        assert_viewer_text(&saved, needle);
    }

