    #[test]
    fn a_shorter_paragraph_closes_the_gap_above_a_listing() {
        let bytes = flow_pdf(
            b"BT /F1 10 Tf \
1 0 0 1 72 500 Tm (Open the terminal and create a project folder named ch02.) Tj \
1 0 0 1 72 488 Tm (You can also clone the repository and then move into it.) Tj \
1 0 0 1 72 476 Tm (Enter the ch02 folder:) Tj \
/F1 10 Tf \
1 0 0 1 60 456 Tm (>) Tj \
/F2 10 Tf \
1 0 0 1 72 456 Tm (python -m venv env_ch02 don\x92t) Tj \
1 0 0 1 120 446 Tm (echo hello) Tj \
/F1 10 Tf \
1 0 0 1 72 436 Tm (Create and activate a virtual environment with venv now.) Tj \
ET",
        );
        let painted = paint_translation(
            &bytes,
            &[
                (0, "进入ch02文件夹：".into()),
                (1, "使用venv创建并激活虚拟环境：".into()),
            ],
        );
        let mut rows: Vec<(f32, Vec<(f32, String)>)> = Vec::new();
        for glyph in &painted.glyphs {
            if glyph.unicode.is_empty() {
                continue;
            }
            if let Some(row) = rows
                .iter_mut()
                .find(|(y, _)| (*y - glyph.matrix[5]).abs() < 0.8)
            {
                row.1.push((glyph.matrix[4], glyph.unicode.clone()));
            } else {
                rows.push((
                    glyph.matrix[5],
                    vec![(glyph.matrix[4], glyph.unicode.clone())],
                ));
            }
        }
        let mut rows: Vec<(f32, String)> = rows
            .into_iter()
            .map(|(y, mut parts)| {
                parts.sort_by(|left, right| left.0.total_cmp(&right.0));
                let text: String = parts.into_iter().map(|(_, text)| text).collect();
                (y, text)
            })
            .collect();
        rows.sort_by(|left, right| right.0.total_cmp(&left.0));
        let intro = rows.iter().find(|(_, text)| text.contains('进')).unwrap().0;
        let code_row = rows
            .iter()
            .find(|(_, text)| text.contains("python"))
            .unwrap_or_else(|| panic!("listing missing: {rows:?}"));
        assert!(
            code_row.1.contains("python -m venv"),
            "listing lost its spaces: {}",
            code_row.1
        );
        assert!(
            code_row.1.contains('>') && (code_row.1.contains('’') || code_row.1.contains('\'')),
            "listing dropped the prompt mark or the apostrophe: {}",
            code_row.1
        );
        let copies = rows
            .iter()
            .filter(|(_, text)| text.contains("python"))
            .count();
        assert_eq!(copies, 1, "listing was drawn twice: {rows:?}");
        let echo = rows
            .iter()
            .filter(|(_, text)| text.contains("echo"))
            .collect::<Vec<_>>();
        assert_eq!(echo.len(), 1, "indented continuation: {rows:?}");
        let code = code_row.0;
        let echo_y = echo[0].0;
        assert!(
            (code - echo_y - 10.0).abs() < 4.0,
            "indented continuation split from the listing: code {code:.1} echo {echo_y:.1}"
        );
        let follow = rows.iter().find(|(_, text)| text.contains('虚')).unwrap().0;
        let line = 15.0;
        let source_gap = 20.0;
        assert!(
            intro - code <= source_gap + line,
            "listing gap {:.1} exceeds the source gap plus one line (intro {intro:.1} code {code:.1})",
            intro - code
        );
        assert!(
            code - follow <= source_gap + line,
            "paragraph under the listing stayed low: code {code:.1} follow {follow:.1}"
        );
        assert!(
            code > 456.0 + 4.0,
            "listing stayed on the English baseline {code:.1}"
        );
        assert!(
            follow > 436.0 + 4.0,
            "paragraph after the listing stayed on the English baseline {follow:.1}"
        );
    }

    #[test]
    fn a_listing_keeps_its_leading_and_the_annotation_stays_on_the_code_line() {
        let bytes = listing_annotation_pdf();
        let mut doc = PdfDocument::open_bytes(&bytes).unwrap();
        let mut extraction = doc.extract();
        let segmentation = crate::segment::segment_placed(
            &extraction.glyphs,
            &crate::segment::SegmentFlags::default(),
            &extraction.regions,
            &extraction.pages,
        );
        for (id, reason) in &segmentation.kept {
            extraction.mark_kept(*id, reason.clone()).unwrap();
        }
        let mut chars: Vec<u32> = "拆分链最后组合成一条链接下来运行整条归约链"
            .chars()
            .map(|ch| ch as u32)
            .collect();
        for seg in &segmentation.segments {
            chars.extend(seg.text.chars().map(|ch| ch as u32));
        }
        let segments: Vec<_> = segmentation
            .segments
            .iter()
            .map(|seg| {
                let translated = if seg.text.contains("Split") {
                    "拆分链".to_string()
                } else if seg.text.contains("Finally") {
                    "最后组合成一条链".to_string()
                } else if seg.text.contains("combined chain") {
                    "接下来运行整条归约链".to_string()
                } else {
                    seg.text.clone()
                };
                TranslatedSegment {
                    id: seg.id,
                    page_index: seg.page_index,
                    glyph_ids: seg.glyph_ids.clone(),
                    source: seg.text.clone(),
                    translated,
                }
            })
            .collect();
        doc.rewrite(
            &mut extraction,
            &TranslateReport {
                segments,
                calls: 0,
                cache_hits: 0,
            },
            &RewriteOptions {
                font_bytes: Some(box_ttf(&chars)),
                ..RewriteOptions::default()
            },
        )
        .unwrap();
        let painted = PdfDocument::open_bytes(&doc.save_bytes().unwrap())
            .unwrap()
            .extract();
        let mut code: Vec<(f32, String)> = Vec::new();
        for glyph in &painted.glyphs {
            if glyph.font_name.contains("Courier") && !glyph.unicode.trim().is_empty() {
                if let Some(row) = code
                    .iter_mut()
                    .find(|(y, _)| (*y - glyph.matrix[5]).abs() < 0.8)
                {
                    row.1.push_str(&glyph.unicode);
                } else {
                    code.push((glyph.matrix[5], glyph.unicode.clone()));
                }
            }
        }
        code.sort_by(|left, right| right.0.total_cmp(&left.0));
        let chunks = code
            .iter()
            .find(|(_, text)| text.contains("text_chunks"))
            .unwrap_or_else(|| panic!("listing missing: {code:?}"));
        let map_line = code
            .iter()
            .find(|(_, text)| text.contains("summarize_map"))
            .unwrap_or_else(|| panic!("continuation missing: {code:?}"));
        let close = code
            .iter()
            .find(|(_, text)| text.trim() == ")")
            .unwrap_or_else(|| panic!("closing bracket missing: {code:?}"));
        assert!(
            (chunks.0 - map_line.0 - 10.0).abs() < 0.6,
            "listing re-spaced: chunks {:.2} map {:.2}",
            chunks.0,
            map_line.0
        );
        assert!(
            (map_line.0 - close.0 - 10.0).abs() < 0.6,
            "listing re-spaced: map {:.2} close {:.2}",
            map_line.0,
            close.0
        );
        assert!(
            chunks.0 > 470.0 + 4.0,
            "listing stayed on the English baseline {:.2}",
            chunks.0
        );
        let label: Vec<&Glyph> = painted
            .glyphs
            .iter()
            .filter(|glyph| {
                glyph.unicode.chars().any(is_han_char)
                    && glyph.unicode != "最"
                    && glyph.matrix[4] > 200.0
            })
            .collect();
        assert!(
            !label.is_empty(),
            "annotation missing: {}",
            painted.plain_text()
        );
        let label_y = label[0].matrix[5];
        let label_x = label
            .iter()
            .map(|glyph| glyph.matrix[4])
            .fold(f32::MAX, f32::min);
        assert!(
            (label_y - chunks.0).abs() < 0.6,
            "annotation y {label_y:.2} code y {:.2}",
            chunks.0
        );
        assert!((label_x - 280.0).abs() < 0.8, "annotation x {label_x:.2}");
        assert!(
            (label[0].font_size - 9.0).abs() < 0.15,
            "annotation size {}",
            label[0].font_size
        );
        let arrow = painted.regions.iter().find(|region| {
            region.kind == "path"
                && (region.bbox[2] - region.bbox[0]).abs() > 8.0
                && (region.bbox[2] - region.bbox[0]).abs() < 30.0
                && (region.bbox[3] - region.bbox[1]).abs() < 3.0
                && region.bbox[0] > 200.0
        });
        let arrow = arrow.unwrap_or_else(|| panic!("arrow missing: {:?}", painted.regions));
        let arrow_y = arrow.bbox[1];
        let moved = chunks.0 - 470.0;
        assert!(
            (arrow_y - (471.0 + moved)).abs() < 0.8,
            "arrow y {arrow_y:.2} expected {:.2} (code moved {moved:.2})",
            471.0 + moved
        );
        let follow = painted
            .glyphs
            .iter()
            .find(|glyph| glyph.unicode.contains('下'))
            .unwrap_or_else(|| panic!("paragraph under the listing missing"));
        assert!(
            (chunks.0 - follow.matrix[5] - 40.0).abs() < 8.0,
            "paragraph under the listing split away: code {:.2} follow {:.2}",
            chunks.0,
            follow.matrix[5]
        );
    }

    #[test]
    fn a_body_line_fills_the_column_before_the_last_line() {
        // 36 source letters at 5pt set a 180pt column. The translation stops
        // before `JupyterNotebook`, which does not fit, and the line still
        // has to reach the column edge.
        let first = "Read the appendix before continuing.";
        let content = format!(
            "BT /F1 10 Tf \
1 0 0 1 72 700 Tm ({first}) Tj \
1 0 0 1 72 686 Tm ({first}) Tj ET"
        );
        let bytes = contents_pdf(content.as_bytes());
        let zh = "如果对这些任务不熟悉请查阅附录获取指导并按照JupyterNotebook环境的说明。";
        let painted = paint_translation(&bytes, &[(0, zh.into())]);
        let column_right = 72.0 + first.len() as f32 * 5.0;
        let mut rows: Vec<(f32, f32, f32, String)> = Vec::new();
        for glyph in &painted.glyphs {
            if !glyph.unicode.chars().any(is_han_char) && !glyph.font_name.starts_with("RPTCJK") {
                continue;
            }
            let right = glyph.matrix[4] + glyph.advance[0];
            if let Some(row) = rows
                .iter_mut()
                .find(|(y, _, _, _)| (*y - glyph.matrix[5]).abs() < 0.8)
            {
                row.1 = row.1.min(glyph.matrix[4]);
                row.2 = row.2.max(right);
                row.3.push_str(&glyph.unicode);
            } else {
                rows.push((
                    glyph.matrix[5],
                    glyph.matrix[4],
                    right,
                    glyph.unicode.clone(),
                ));
            }
        }
        rows.sort_by(|left, right| right.0.total_cmp(&left.0));
        assert!(rows.len() >= 2, "the paragraph should wrap: {rows:?}");
        assert!(
            rows[0].3.contains("Jupyter") && !rows[0].3.contains("Notebook"),
            "the long token should break at camelCase and fill the line: {rows:?}"
        );
        for (y, left, right, text) in rows.iter().take(rows.len() - 1) {
            let available = column_right - left;
            let fill = (right - left) / available;
            assert!(
                fill >= 0.90,
                "line at y={y:.1} fills {fill:.2} of the column ({left:.1}-{right:.1}, edge {column_right:.1}): {text}"
            );
        }
        assert_max_cjk_gap(&painted, 0.15);
    }

    fn assert_max_cjk_gap(painted: &Extraction, max_em: f32) {
        let mut glyphs: Vec<&Glyph> = painted
            .glyphs
            .iter()
            .filter(|glyph| glyph.unicode.chars().any(is_han_char))
            .collect();
        glyphs.sort_by(|left, right| {
            right.matrix[5]
                .total_cmp(&left.matrix[5])
                .then(left.matrix[4].total_cmp(&right.matrix[4]))
        });
        for pair in glyphs.windows(2) {
            if (pair[0].matrix[5] - pair[1].matrix[5]).abs() > 0.8 {
                continue;
            }
            if !is_han_char(pair[0].unicode.chars().next().unwrap_or(' '))
                || !is_han_char(pair[1].unicode.chars().next().unwrap_or(' '))
            {
                continue;
            }
            let size = pair[0].font_size.max(0.1);
            // The box face advances 0.6em. The extract advance includes the
            // justification gap, so the extra is the step past that em.
            let step = pair[1].matrix[4] - pair[0].matrix[4];
            let extra = step / size - 0.6;
            assert!(
                extra <= max_em + 0.02,
                "gap {extra:.3}em between {} and {} at y={:.1}",
                pair[0].unicode,
                pair[1].unicode,
                pair[0].matrix[5]
            );
        }
    }

    fn assert_no_glyph_overlap(painted: &Extraction) {
        let glyphs: Vec<&Glyph> = painted
            .glyphs
            .iter()
            .filter(|glyph| !glyph.invisible && glyph.unicode.chars().any(|ch| !ch.is_whitespace()))
            .collect();
        for index in 0..glyphs.len() {
            for other in index + 1..glyphs.len() {
                let a = glyphs[index];
                let b = glyphs[other];
                if a.page_index != b.page_index {
                    continue;
                }
                let area = bbox_overlap_area(a.bbox, b.bbox);
                let smaller = bbox_area(a.bbox).min(bbox_area(b.bbox)).max(0.1);
                if area > 1.0 && area > smaller * 0.15 {
                    panic!(
                        "glyphs overlap {:.1}pt² ({:.0}% of the smaller): {:?} {:?} and {:?} {:?}",
                        area,
                        100.0 * area / smaller,
                        a.unicode,
                        a.bbox,
                        b.unicode,
                        b.bbox
                    );
                }
            }
        }
        // A decorative quote may be a text glyph or a tall narrow path.
        // Both have to clear the answer line.
        for glyph in &glyphs {
            if !glyph.unicode.chars().any(is_han_char) {
                continue;
            }
            for region in &painted.regions {
                if region.page_index != glyph.page_index
                    || region.kind != "path"
                    || !is_decorative_vector(region.bbox)
                {
                    continue;
                }
                let area = bbox_overlap_area(glyph.bbox, region.bbox);
                let smaller = bbox_area(glyph.bbox).min(bbox_area(region.bbox)).max(0.1);
                if area > 1.0 && area > smaller * 0.15 {
                    panic!(
                        "decorative vector overlaps {:?} {:?} by {:.1}pt²",
                        glyph.unicode, region.bbox, area
                    );
                }
            }
        }
    }

    fn bbox_area(bbox: [f32; 4]) -> f32 {
        (bbox[2] - bbox[0]).abs() * (bbox[3] - bbox[1]).abs()
    }

    fn bbox_overlap_area(a: [f32; 4], b: [f32; 4]) -> f32 {
        let left = a[0].min(a[2]).max(b[0].min(b[2]));
        let right = a[0].max(a[2]).min(b[0].max(b[2]));
        let bottom = a[1].min(a[3]).max(b[1].min(b[3]));
        let top = a[1].max(a[3]).min(b[1].max(b[3]));
        (right - left).max(0.0) * (top - bottom).max(0.0)
    }

    fn hanging_label_rights(painted: &Extraction, body_x: f32) -> Vec<f32> {
        let mut rows: Vec<Vec<&Glyph>> = Vec::new();
        for glyph in &painted.glyphs {
            if !glyph.unicode.chars().any(is_han_char) {
                continue;
            }
            if let Some(row) = rows
                .iter_mut()
                .find(|row| (row[0].matrix[5] - glyph.matrix[5]).abs() < 1.5)
            {
                row.push(glyph);
            } else {
                rows.push(vec![glyph]);
            }
        }
        let mut rights = Vec::new();
        for mut row in rows {
            row.sort_by(|left, right| left.matrix[4].total_cmp(&right.matrix[4]));
            let mut label_right = None;
            for glyph in row {
                if glyph.matrix[4] >= body_x - 1.5 {
                    break;
                }
                let right = glyph.bbox[0].max(glyph.bbox[2]).max(glyph.matrix[4]);
                if right >= body_x - 1.0 {
                    label_right = None;
                    break;
                }
                label_right = Some(right);
            }
            if let Some(right) = label_right {
                rights.push(right);
            }
        }
        rights
    }

    fn assert_prompt_labels_have_no_colon(painted: &Extraction, body_x: f32) {
        let colon = painted.glyphs.iter().find(|glyph| {
            matches!(glyph.unicode.as_str(), "：" | ":") && glyph.matrix[4] < body_x - 1.0
        });
        assert!(
            colon.is_none(),
            "prompt label painted a colon at x={:.1}",
            colon.map(|glyph| glyph.matrix[4]).unwrap_or(0.0)
        );
    }

    fn assert_label_smaller_than_body(painted: &Extraction, label: &str, body: &str) {
        let label_size = painted
            .glyphs
            .iter()
            .filter(|glyph| glyph.unicode == label)
            .min_by(|left, right| left.matrix[4].total_cmp(&right.matrix[4]))
            .unwrap_or_else(|| panic!("missing {label}"))
            .font_size;
        let body_size = painted
            .glyphs
            .iter()
            .find(|glyph| glyph.unicode == body)
            .unwrap_or_else(|| panic!("missing {body}"))
            .font_size;
        assert!(
            label_size < body_size * 0.92 && label_size > body_size * 0.75,
            "label {label_size:.2} is not slightly smaller than body {body_size:.2}"
        );
    }

    #[test]
    fn a_prompt_label_keeps_the_source_hanging_indent() {
        // Small caps `INSTRUCTION` at the left, body at x=117. Type1 width
        // 500 means size 9.5 advances 4.75pt, so the label is placed with Tm.
        let bytes = contents_pdf_named(
            b"BT \
/F1 9.5 Tf 1 0 0 1 65 400 Tm (I) Tj \
/F1 7.6 Tf 1 0 0 1 70 400 Tm (NSTRUCTION) Tj \
/F1 9.5 Tf 1 0 0 1 117 400 Tm (Sum the palindromes in this sequence: 13, 1331.) Tj \
/F1 9.5 Tf 1 0 0 1 79 380 Tm (E) Tj \
/F1 7.6 Tf 1 0 0 1 84 380 Tm (XAMPLE) Tj \
/F1 9.5 Tf 1 0 0 1 117 380 Tm (33 is a palindrome.) Tj \
ET",
            "FranklinGothic-Book",
        );
        let painted = paint_translation(
            &bytes,
            &[
                (0, "指令：求此序列中回文数之和：13、1331。".into()),
                (1, "示例 33 是一个回文".into()),
            ],
        );
        let mut label_x = None;
        let mut body_x = None;
        let mut example_label = None;
        let mut example_body = None;
        for glyph in &painted.glyphs {
            if glyph.unicode == "指" {
                label_x = Some(glyph.matrix[4]);
            }
            if glyph.unicode == "求" {
                body_x = Some(glyph.matrix[4]);
            }
            if glyph.unicode == "示" {
                example_label = Some(glyph.matrix[4]);
            }
            if glyph.unicode == "3" && glyph.matrix[5] < 390.0 {
                example_body = example_body.or(Some(glyph.matrix[4]));
            }
        }
        let label_x = label_x.expect("missing 指令");
        let body_x = body_x.expect("missing body");
        assert!(
            (body_x - 117.0).abs() < 6.0,
            "prose started at the left margin {body_x:.1}"
        );
        assert!(
            body_x > label_x + 8.0,
            "label and prose collapsed: label {label_x:.1} body {body_x:.1}"
        );
        let example_label = example_label.expect("missing 示例");
        let example_body = example_body.expect("missing 33");
        assert!(
            (example_label - label_x).abs() < 3.0,
            "示例 and 指令 do not share a left edge: {example_label:.1} vs {label_x:.1}"
        );
        assert!(
            example_body > 110.0,
            "示例 body stayed in the margin at {example_body:.1}"
        );
        assert!(
            (example_body - body_x).abs() < 2.0,
            "sample bodies do not share an x: {body_x:.1} vs {example_body:.1}"
        );
        assert_prompt_labels_have_no_colon(&painted, body_x);
        assert_label_smaller_than_body(&painted, "指", "求");
        let rights = hanging_label_rights(&painted, body_x);
        let span = rights.iter().copied().fold(0.0f32, f32::max)
            - rights.iter().copied().fold(f32::MAX, f32::min);
        assert!(
            rights.len() >= 2 && span < 1.5,
            "label edges are not on one axis: {rights:?}"
        );
        assert_no_glyph_overlap(&painted);
    }

    #[test]
    fn a_prompt_quote_does_not_collide_with_the_sample() {
        // The 22pt quote sits 4.6pt above the continuation, which is how the
        // source line-grouper folds it into `palin- “ dromes`.
        let bytes = contents_pdf_named(
            b"BT \
/F1 9.5 Tf 1 0 0 1 117 210 Tm (I apologize for the previous palin-) Tj \
/F1 22 Tf 1 0 0 1 102 203 Tm (\") Tj \
/F1 9.5 Tf 1 0 0 1 117 198.4 Tm (dromes in this sequence: 13, 99, 56, 232, and 7.) Tj \
ET",
            "FranklinGothic-Book",
        );
        let painted = paint_translation(
            &bytes,
            &[(
                0,
                "我为之前的疏忽道歉。让我们正确地识别并求和此序列中的回文数：13, 99, 56, 232 和 7。".into(),
            )],
        );
        let mut nines = Vec::new();
        let mut twos = Vec::new();
        for glyph in &painted.glyphs {
            if glyph.unicode == "9" {
                nines.push((glyph.matrix[4], glyph.matrix[5]));
            }
            if glyph.unicode == "2" {
                twos.push((glyph.matrix[4], glyph.matrix[5]));
            }
            if glyph.unicode.chars().any(is_han_char) {
                assert!(
                    glyph.matrix[4] > 110.0,
                    "sample prose fell into the quote margin at x={:.1} ({})",
                    glyph.matrix[4],
                    glyph.unicode
                );
            }
        }
        for (nx, ny) in &nines {
            for (tx, ty) in &twos {
                assert!(
                    (ny - ty).abs() > 1.0 || (nx - tx).abs() > 2.0,
                    "99 and 232 share a point ({nx:.1},{ny:.1}) ({tx:.1},{ty:.1})"
                );
            }
        }
        let mut quote_width = None;
        let mut quote_right = None;
        let mut answer_x = None;
        for glyph in &painted.glyphs {
            if glyph.font_size > 14.0 && is_quote_mark(&glyph.unicode) {
                let right = glyph.bbox[0].max(glyph.bbox[2]);
                let left = glyph.bbox[0].min(glyph.bbox[2]);
                quote_width = Some(right - left);
                quote_right = Some(right);
            }
            if glyph.unicode.chars().any(is_han_char) {
                answer_x = Some(answer_x.map_or(glyph.matrix[4], |x: f32| x.min(glyph.matrix[4])));
            }
        }
        if let (Some(quote_width), Some(quote_right), Some(answer_x)) =
            (quote_width, quote_right, answer_x)
        {
            assert!(
                quote_width < 12.0,
                "decorative quote stayed a full em wide ({quote_width:.1}pt)"
            );
            assert!(
                quote_right + 0.8 < answer_x,
                "quote right {quote_right:.1} overlaps the answer at {answer_x:.1}"
            );
            assert!(
                (answer_x - 117.0).abs() < 4.0,
                "answer left the source x: {answer_x:.1}"
            );
        }
        assert_no_glyph_overlap(&painted);
    }

    #[test]
    fn a_hanging_quote_is_not_repeated_inside_the_answer() {
        // The 22pt mark is painted from the source glyph. A translation that
        // still opens with it must not keep that character in the line.
        assert_eq!(trim_leading_quotes("“ 和 900。"), "和 900。");
        assert_eq!(trim_leading_quotes("  “和 900。"), "和 900。");
        assert_eq!(trim_leading_quotes("科技"), "科技");
        assert_eq!(trim_leading_quotes("“科技”"), "科技”");
    }

    #[test]
    fn a_decorative_vector_counts_in_the_overlap_test() {
        let quote = [102.0, 116.0, 112.3, 138.6];
        let answer = [117.0, 124.0, 126.0, 134.0];
        assert!(is_decorative_vector(quote));
        assert!(!is_decorative_vector([72.0, 100.0, 460.0, 101.2]));
        assert!(!is_decorative_vector([90.0, 90.0, 200.0, 160.0]));
        assert!(bbox_overlap_area(quote, answer) < 0.1);
        let wide = [102.0, 116.0, 124.0, 138.6];
        assert!(bbox_overlap_area(wide, answer) > 1.0);
    }

    #[test]
    fn a_cross_page_callout_keeps_body_colour_and_has_no_indent() {
        let blue = Color::rgb(0.278, 0.42, 0.522);
        let gray = Color::gray(0.148);
        let mut glyphs = Vec::new();
        let mut label = ink_glyph(0, 105.0, 100.0, 8.5, "DEFINITION");
        label.fill_color = blue.clone();
        label.font_name = "FranklinGothic-Demi".into();
        label.bbox = [105.0, 93.0, 150.0, 108.0];
        glyphs.push(label);
        let mut id = 1u32;
        for (index, ch) in "The window".chars().enumerate() {
            let x = 160.0 + index as f32 * 4.5;
            let mut glyph = ink_glyph(id, x, 100.0, 10.0, &ch.to_string());
            glyph.fill_color = gray.clone();
            glyph.bbox = [x, 92.0, x + 4.2, 108.0];
            glyphs.push(glyph);
            id += 1;
        }
        for (index, ch) in "stays here".chars().enumerate() {
            let x = 105.0 + index as f32 * 5.0;
            let mut glyph = ink_glyph(id, x, 86.0, 10.0, &ch.to_string());
            glyph.fill_color = gray.clone();
            glyph.bbox = [x, 78.0, x + 4.6, 94.0];
            glyphs.push(glyph);
            id += 1;
        }
        for (index, ch) in "word continues on the next page of this callout"
            .chars()
            .enumerate()
        {
            let x = 114.0 + index as f32 * 6.0;
            let mut glyph = ink_glyph(id, x, 700.0, 10.0, &ch.to_string());
            glyph.page_index = 1;
            glyph.fill_color = gray.clone();
            glyph.bbox = [x, 692.0, x + 5.5, 708.0];
            glyphs.push(glyph);
            id += 1;
        }
        for (index, ch) in "and the following line stays flush".chars().enumerate() {
            let x = 114.0 + index as f32 * 6.0;
            let mut glyph = ink_glyph(id, x, 686.0, 10.0, &ch.to_string());
            glyph.page_index = 1;
            glyph.fill_color = gray.clone();
            glyph.bbox = [x, 678.0, x + 5.5, 694.0];
            glyphs.push(glyph);
            id += 1;
        }
        let text =
            "定义：其中一个词元大致对应一个词。例如模型可以处理很多词元并且在下一页继续写完。";
        let mut cmap = std::collections::HashMap::new();
        for (cid, ch) in (1u16..).zip(text.chars()) {
            cmap.insert(ch as u32, (cid, 1000));
        }
        let font = crate::font::SubsetFont {
            bytes: Vec::new(),
            units_per_em: 1000,
            glyphs: cmap,

            fallback: None,
            notice: None,
        };
        let extraction = Extraction {
            coordinate_space: "pdf",
            pages: Vec::new(),
            glyphs: Vec::new(),
            regions: Vec::new(),
            diagnostics: Vec::new(),
        };
        let refs: Vec<&Glyph> = glyphs.iter().collect();
        let drawn = layout_across_pages(
            &refs,
            text,
            &font,
            &extraction,
            "F",
            0.0,
            CjkMeasure::resolve(0.90, 1.60),
            &HashMap::new(),
        )
        .expect("callout crosses the page");
        let label = drawn
            .iter()
            .find(|line| line.text.starts_with("定义"))
            .expect("label");
        assert_eq!(label.page, 0);
        assert_eq!(label.color, blue);
        assert!((label.x - 105.0).abs() < 1.0, "label x {}", label.x);
        let continuation: Vec<_> = drawn.iter().filter(|line| line.page == 1).collect();
        assert!(
            !continuation.is_empty(),
            "page 2 kept no lines ({})",
            drawn.len()
        );
        for line in &continuation {
            assert_eq!(line.color, gray, "continuation colour {:?}", line.color);
            assert!(
                (line.x - 114.0).abs() < 1.0,
                "continuation indent x={} text={}",
                line.x,
                line.text
            );
        }
        let mut pages: Vec<(u32, String)> = Vec::new();
        for line in &drawn {
            if line.text.starts_with("定义") {
                continue;
            }
            if let Some(slot) = pages.iter_mut().find(|(page, _)| *page == line.page) {
                slot.1.push_str(&line.text);
            } else {
                pages.push((line.page, line.text.clone()));
            }
        }
        pages.sort_by_key(|(page, _)| *page);
        for pair in pages.windows(2) {
            let left = &pair[0].1;
            let right = &pair[1].1;
            assert!(
                !(left.ends_with('个') && right.starts_with('词')),
                "一个|词 across pages: {left:?} | {right:?}"
            );
            assert!(
                !(left.ends_with("一个") && right.starts_with('词')),
                "一个|词 across pages: {left:?} | {right:?}"
            );
        }
    }

    #[test]
    fn a_note_callout_puts_the_label_at_the_source_x_and_does_not_letter_space() {
        let (label, body) = split_callout_han("请注意，在完整的《白鲸》文本上运行。").unwrap();
        assert_eq!(label, "注意：");
        assert_eq!(body, "在完整的《白鲸》文本上运行。");
        assert!(split_callout_han("注意，创建结构良好的提示词。")
            .unwrap()
            .1
            .starts_with("创建"));

        let blue = Color::rgb(0.2, 0.35, 0.55);
        let gray = Color::gray(0.2);
        let mut glyphs = Vec::new();
        let mut id = 0u32;
        let mut place =
            |glyphs: &mut Vec<Glyph>, x: f32, y: f32, size: f32, text: &str, color: &Color| {
                let mut cursor = x;
                for ch in text.chars() {
                    let width = size * 0.48;
                    let mut glyph = ink_glyph(id, cursor, y, size, &ch.to_string());
                    glyph.fill_color = color.clone();
                    glyph.bbox = [cursor, y - 2.0, cursor + width, y + size * 0.75];
                    glyph.advance = [width, 0.0];
                    glyphs.push(glyph);
                    id += 1;
                    cursor += width;
                }
                cursor
            };
        // NOTE sits in the margin. The sentence starts 10pt later, under the
        // column-gap trigger, and wrapped lines come back to the label edge.
        place(&mut glyphs, 114.0, 560.0, 8.0, "NOTE", &blue);
        let text_x = 140.0f32;
        // A space in the label gap must not become the body x.
        let _ = place(&mut glyphs, 132.0, 560.0, 10.0, " ", &gray);
        let _ = place(
            &mut glyphs,
            text_x,
            560.0,
            10.0,
            "Keep in mind that running this sample gets expensive today indeed",
            &gray,
        );
        for y in [546.0, 532.0, 518.0] {
            let _ = place(
                &mut glyphs,
                114.0,
                y,
                10.0,
                "the following line of this note stays flush with the label edge",
                &gray,
            );
        }
        let text = "请注意，在完整的《白鲸》文本上运行代码可能会比较昂贵。提供的 MobyDickFileNameIsLong 文件很短所以这一段还要继续写完几行说明。";
        let mut cmap = std::collections::HashMap::new();
        for (cid, ch) in (1u16..).zip(text.chars()) {
            cmap.insert(ch as u32, (cid, 1000));
        }
        let font = crate::font::SubsetFont {
            bytes: Vec::new(),
            units_per_em: 1000,
            glyphs: cmap,

            fallback: None,
            notice: None,
        };
        let extraction = Extraction {
            coordinate_space: "pdf",
            pages: Vec::new(),
            glyphs: Vec::new(),
            regions: Vec::new(),
            diagnostics: Vec::new(),
        };
        let refs: Vec<&Glyph> = glyphs.iter().collect();
        let drawn = layout_segment(
            &refs,
            text,
            &font,
            &extraction,
            false,
            "F",
            0.0,
            CjkMeasure::resolve(0.90, 1.60),
        )
        .expect("note callout lays out");
        let label = drawn
            .iter()
            .find(|line| line.text.starts_with("注意"))
            .expect("label");
        assert_eq!(label.color, blue);
        assert!((label.x - 114.0).abs() < 1.0, "label x {}", label.x);
        let body: Vec<_> = drawn
            .iter()
            .filter(|line| !line.text.starts_with("注意"))
            .collect();
        assert!(body.len() >= 2, "callout kept {} lines", body.len());
        assert!(
            (body[0].x - 140.0).abs() < 1.5,
            "body x {} text {}",
            body[0].x,
            body[0].text
        );
        assert_eq!(body[0].color, gray);
        assert!(
            !body[0].text.starts_with('请') && !body[0].text.starts_with("注意"),
            "label stayed in the body: {}",
            body[0].text
        );
        for line in body.iter().skip(1) {
            assert_eq!(line.color, gray);
            assert!(
                (line.x - 114.0).abs() < 1.5,
                "continuation indent x={} text={}",
                line.x,
                line.text
            );
        }
        let cap = body[0].size * 0.15 + 0.02;
        for line in &body {
            assert!(
                line.gaps.iter().all(|gap| *gap <= cap),
                "gap exceeded {cap:.2} on {}: {:?}",
                line.text,
                line.gaps
            );
        }
        assert!(
            body[0].gaps.iter().all(|gap| *gap == 0.0),
            "short note line was letter-spaced: {} {:?}",
            body[0].text,
            body[0].gaps
        );
    }

    #[test]
    fn a_quoted_line_is_not_a_callout_label() {
        // `definition` is 10 bytes. A line whose 10th byte sits inside `“`
        // must not panic, and it is not a callout.
        assert!(!is_callout_source("EXAMPLE “a quoted sample line”"));
        assert!(is_callout_source("NOTE This stays a callout."));
        assert!(is_callout_source("Definition The term is one paragraph."));
        assert!(!is_callout_source("notebook stays prose"));
    }

    #[test]
    fn a_prompt_block_keeps_one_label_and_does_not_mix_the_input() {
        // `TEXT` is small caps. The model left the English label and translated
        // the sentence, and the answer quotes that sentence in English.
        let bytes = contents_pdf_named(
            b"BT \
/F1 9.5 Tf 1 0 0 1 65 400 Tm (I) Tj \
/F1 7.6 Tf 1 0 0 1 70 400 Tm (NSTRUCTION) Tj \
/F1 9.5 Tf 1 0 0 1 117 400 Tm (Classify the following text into one category.) Tj \
/F1 9.5 Tf 1 0 0 1 94 386 Tm (T) Tj \
/F1 7.6 Tf 1 0 0 1 99 386 Tm (EXT) Tj \
/F1 9.5 Tf 1 0 0 1 117 386 Tm (Headphones provide immersive audio.) Tj \
/F1 9.5 Tf 1 0 0 1 117 360 Tm (The text Headphones provide immersive audio experiences for music lovers and) Tj \
/F1 22 Tf 1 0 0 1 102 353 Tm (\") Tj \
/F1 9.5 Tf 1 0 0 1 117 348.4 Tm (gamers alike. It should be classified as tech.) Tj \
ET",
            "FranklinGothic-Book",
        );
        let painted = paint_translation(
            &bytes,
            &[
                (0, "说明：将以下文本归类到其中一个类别。".into()),
                (
                    1,
                    "TEXT耳机为音乐爱好者和游戏玩家提供沉浸式音频体验。".into(),
                ),
                (
                    2,
                    "文本“Headphones provide immersive audio experiences for music lovers and “ gamers alike.” 应被归类为“科技”，因为它讨论了与技术相关的产品及其功能。".into(),
                ),
            ],
        );
        let mut label_x = None;
        let mut body_x = None;
        for glyph in &painted.glyphs {
            if glyph.unicode == "T" {
                panic!(
                    "the small-caps T was painted at x={:.1} y={:.1}",
                    glyph.matrix[4], glyph.matrix[5]
                );
            }
            if glyph.unicode == "文" && glyph.matrix[4] < 110.0 {
                label_x = Some(glyph.matrix[4]);
            }
            if glyph.unicode == "耳" {
                body_x = Some(glyph.matrix[4]);
            }
            let latin = glyph.unicode.chars().any(|ch| ch.is_ascii_alphabetic());
            let low = glyph.matrix[5] < 380.0;
            if latin && low {
                panic!(
                    "quoted input stayed in the answer: {} at ({:.1},{:.1})",
                    glyph.unicode, glyph.matrix[4], glyph.matrix[5]
                );
            }
        }
        let label_x = label_x.expect("missing 文本");
        let body_x = body_x.expect("missing 耳机");
        assert!(
            (body_x - 117.0).abs() < 8.0,
            "example body started at {body_x:.1}"
        );
        assert!(body_x > label_x + 8.0, "label and body collapsed");
        assert_prompt_labels_have_no_colon(&painted, body_x);
        assert_label_smaller_than_body(&painted, "文", "耳");
        let rights = hanging_label_rights(&painted, body_x);
        assert!(
            rights.len() >= 2,
            "说明 and 文本 should both hang: {rights:?}"
        );
        let span = rights.iter().copied().fold(0.0f32, f32::max)
            - rights.iter().copied().fold(f32::MAX, f32::min);
        assert!(span < 1.5, "说明 and 文本 are not on one axis: {rights:?}");
        assert_no_glyph_overlap(&painted);
    }

    #[test]
    fn prompt_labels_share_one_colon_axis() {
        let chars: Vec<u32> = "说明：文本指令示例".chars().map(|ch| ch as u32).collect();
        let font = subset_ttf(&box_ttf(&chars), &chars).expect("font");
        let column = PromptColumn {
            right_aligned: true,
            axis: 111.0,
            text_x: 117.0,
        };
        let (instruction, instruction_size, instruction_x) =
            fit_run_in_label("说明：", &column, 117.0, 9.0, &font);
        let (text, text_size, text_x) = fit_run_in_label("文本", &column, 117.0, 9.0, &font);
        assert_eq!(instruction, "说明");
        assert_eq!(text, "文本");
        assert!(
            (instruction_size - 9.0 * PROMPT_LABEL_SCALE).abs() < 0.05,
            "label size {instruction_size} is not the small-caps analog"
        );
        assert!((text_size - instruction_size).abs() < 0.05);
        let instruction_right = instruction_x + measure(&instruction, instruction_size, &font);
        let text_right = text_x + measure(&text, text_size, &font);
        assert!(
            (instruction_right - 111.0).abs() < 0.2 && (text_right - instruction_right).abs() < 0.2,
            "label edges at {instruction_right:.2} and {text_right:.2}"
        );
        assert!(instruction_right < 117.0 - 2.0);
    }

    #[test]
    fn a_decorative_quote_scales_to_the_source_width() {
        let chars = vec!['“' as u32];
        let font = subset_ttf(&box_ttf(&chars), &chars).expect("font");
        let natural = measure("“", 22.0, &font);
        assert!(natural > 12.0, "fixture quote is already narrow: {natural}");
        let line = Drawn {
            page: 0,
            x: 102.2,
            y: 121.1,
            size: 22.0,
            color: Color::black(),
            cids: cids_of("“", &font),
            resource: "F1".into(),
            skew: 0.0,
            text: "“".into(),
            glyph_ids: vec![1],
            widths: vec![10.1],
            gaps: Vec::new(),
            supers: vec![false],
            sup_scale: 1.0,
            sup_rise: 0.0,
        };
        let tz = quote_tz(&line, &[("F1".into(), font)]).expect("quote should scale");
        let painted = natural * tz / 100.0;
        assert!(
            (painted - 10.1).abs() < 0.15,
            "scaled quote is {painted:.2}pt (tz {tz:.1})"
        );
    }

    #[test]
    fn a_scaled_quote_is_its_own_operator_and_clears_the_answer() {
        // The 22pt mark shares the answer segment, so it is redrawn in the
        // CJK face and squeezed back to the source width. `100 Tz` has to be
        // a separate operator; glued onto `Tj` it drops the mark.
        let bytes = contents_pdf_named(
            b"BT \
/F1 22 Tf 1 0 0 1 102.2 193 Tm (\") Tj \
/F1 9.5 Tf 1 0 0 1 117.2 200 Tm (The text should be classified as tech because it discusses products.) Tj \
ET",
            "FranklinGothic-Book",
        );
        let saved = paint_bytes(
            &bytes,
            &[(
                0,
                "文本应被归类为科技，因为它讨论了相关产品及其功能。".into(),
            )],
        );
        assert!(
            !saved.windows(5).any(|window| window == b"Tj100"),
            "horizontal scale was glued onto Tj"
        );
        let painted = PdfDocument::open_bytes(&saved).unwrap().extract();
        let quote = painted
            .glyphs
            .iter()
            .find(|glyph| is_quote_mark(&glyph.unicode) && glyph.font_size >= 14.0);
        let quote = quote.expect("decorative quote was not painted");
        let width = (quote.bbox[2] - quote.bbox[0]).abs();
        assert!(width < 12.0, "quote is still {width:.1}pt wide");
        let answer = painted
            .glyphs
            .iter()
            .find(|glyph| glyph.unicode == "文")
            .expect("answer");
        assert!(
            answer.matrix[4] > quote.bbox[0].max(quote.bbox[2]) + 2.0,
            "answer at {:.1} does not clear the quote ending at {:.1}",
            answer.matrix[4],
            quote.bbox[0].max(quote.bbox[2])
        );
        assert_no_glyph_overlap(&painted);
    }

    #[test]
    fn a_hanging_prompt_label_closes_the_gap_above_it() {
        // The paragraph above shrank from two source lines to one. The next
        // prompt label hangs at x=74 while the paragraph starts at x=120, so
        // a left-edge chain misses it. The spans still overlap. The 22pt
        // answer mark is not a drawn line and has to ride with the answer.
        let size = 9.0;
        let glyphs = vec![
            ink_glyph(1, 102.0, 340.0, size, "N"),
            ink_glyph(2, 102.0, 326.0, size, "t"),
            ink_glyph(10, 74.0, 310.0, size, "I"),
            ink_glyph(11, 126.0, 296.0, size, "H"),
            ink_glyph(20, 111.0, 289.0, 22.0, "“"),
        ];
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![],
            glyphs,
            regions: vec![],
            diagnostics: vec![],
        };
        let by_id = glyph_index(&extraction.glyphs);
        let mut body = test_draw(
            120.0,
            340.0,
            size,
            "现在应用相同的提示对另一个句子进行分类",
            vec![1, 2],
        );
        body.widths = vec![8.0; body.text.chars().count()];
        let mut label = test_draw(74.0, 310.0, size, "说明", vec![10]);
        label.widths = vec![8.0; label.text.chars().count()];
        let mut prose = test_draw(126.0, 310.0, size, "将以下文本归类到其中一个类别", vec![10]);
        prose.widths = vec![8.0; prose.text.chars().count()];
        let mut answer = test_draw(126.0, 296.0, size, "历史分类", vec![11]);
        answer.widths = vec![8.0; answer.text.chars().count()];
        let mut drawn = vec![body, label, prose, answer];
        let shifts = close_column_holes(&mut drawn, &extraction, &by_id);
        let label_y = drawn.iter().find(|item| item.text == "说明").unwrap().y;
        assert!(
            label_y > 310.0 + 8.0,
            "the hanging label stayed on the English baseline at y={label_y}"
        );
        let answer_y = drawn.iter().find(|item| item.text == "历史分类").unwrap().y;
        assert!(
            answer_y > 296.0 + 8.0,
            "the answer stayed on the English baseline at y={answer_y}"
        );
        let quote = shifts
            .iter()
            .find(|shift| shift.ids.contains(&20))
            .expect("decorative quote was left on the English baseline");
        assert!(
            (quote.dy - (answer_y - 296.0)).abs() < 0.4,
            "quote dy {} answer move {}",
            quote.dy,
            answer_y - 296.0
        );
    }

    #[test]
    fn a_prompt_continuation_fills_the_source_line() {
        // `TEXT … in the` and `demise …` are two segments. The Chinese of the
        // first line used to stop early instead of taking the continuation.
        let head =
            "Julius Caesar was a Roman general and statesman who played a pivotal role in the";
        let tail = "demise of the Roman Republic and the rise of the Roman Empire.";
        let content = format!(
            "BT \
/F1 9.5 Tf 1 0 0 1 103 400 Tm (T) Tj \
/F1 7.6 Tf 1 0 0 1 108 400 Tm (EXT) Tj \
/F1 9.5 Tf 1 0 0 1 126 400 Tm ({head}) Tj \
/F1 9.5 Tf 1 0 0 1 126 386 Tm ({tail}) Tj \
/F1 9.5 Tf 1 0 0 1 92 372 Tm (O) Tj \
/F1 7.6 Tf 1 0 0 1 97 372 Tm (UTPUT) Tj \
/F1 9.5 Tf 1 0 0 1 126 372 Tm (only the category) Tj \
ET"
        );
        let bytes = contents_pdf_named(content.as_bytes(), "FranklinGothic-Book");
        let painted = paint_translation(
            &bytes,
            &[
                (0, "文本尤利乌斯凯撒是一位罗马将军和政治家，他在".into()),
                (1, "罗马共和国的衰落和罗马帝国的兴起。".into()),
                (2, "输出：仅输出分类".into()),
            ],
        );
        let han: Vec<&Glyph> = painted
            .glyphs
            .iter()
            .filter(|glyph| glyph.unicode.chars().any(is_han_char))
            .collect();
        let kai = han.iter().find(|glyph| glyph.unicode == "凯").expect("凯");
        let luo = han
            .iter()
            .find(|glyph| glyph.unicode == "落")
            .expect("continuation 落 was dropped");
        assert!(
            (kai.matrix[5] - luo.matrix[5]).abs() < 2.0,
            "落 stayed on its own line at {:.1}, 凯 at {:.1}",
            luo.matrix[5],
            kai.matrix[5]
        );
        let right = han
            .iter()
            .filter(|glyph| (glyph.matrix[5] - kai.matrix[5]).abs() < 1.5)
            .map(|glyph| glyph.bbox[2].max(glyph.bbox[0]))
            .fold(kai.matrix[4], f32::max);
        assert!(
            right > 126.0 + 160.0,
            "the Julius line still ends early at {right:.1}"
        );
        let output = han
            .iter()
            .find(|glyph| glyph.unicode == "输")
            .expect("输出");
        assert!(
            output.matrix[5] > 372.0 + 6.0,
            "the unused wrap left 输出 at {:.1}",
            output.matrix[5]
        );
        let body_x = han
            .iter()
            .filter(|glyph| {
                (glyph.matrix[5] - kai.matrix[5]).abs() < 1.5
                    && glyph.unicode != "文"
                    && glyph.unicode != "本"
            })
            .map(|glyph| glyph.matrix[4])
            .fold(f32::MAX, f32::min);
        assert!(
            (body_x - 126.0).abs() < 4.0,
            "continuation content x is {body_x:.1}"
        );
    }

    #[test]
    fn a_title_case_label_uses_the_ink_edge_not_the_word_space() {
        let mut glyphs = vec![
            letter_glyph(1, 103.08, 4.76, 4.74, "T"),
            letter_glyph(2, 107.84, 5.14, 5.12, "e"),
            letter_glyph(3, 112.99, 4.14, 4.17, "x"),
            // The advance reaches `Java`; the ink stops at the stem of `t`.
            letter_glyph(4, 117.13, 9.06, 3.03, "t"),
            letter_glyph(5, 126.19, 3.78, 3.79, "J"),
            letter_glyph(6, 129.97, 5.16, 5.12, "a"),
        ];
        let run = run_in_label(&[ink_of(&glyphs)]).expect("Text Java");
        assert!((run.text_x - 126.19).abs() < 0.05, "text x {}", run.text_x);
        assert!(
            (run.label_right - 120.16).abs() < 0.2,
            "label right followed the word space: {}",
            run.label_right
        );
        // `Text: {chunk}` has the same column gap, and it is code.
        glyphs[4].unicode = "{".into();
        assert!(run_in_label(&[ink_of(&glyphs)]).is_none());
        // `Text classification` opens with a lowercase body.
        glyphs[4].unicode = "c".into();
        assert!(run_in_label(&[ink_of(&glyphs)]).is_none());
    }

    #[test]
    fn a_title_case_prompt_label_shares_the_colon_axis() {
        // `Text Java` is title case, not small caps. The word space lives in
        // the advance of `t`, and the translation is `文本 Java` with no colon.
        let (label, rest) =
            split_run_in_label("文本 Java 是一种流行的编程语言").expect("spaced 文本");
        assert!(label.starts_with("文本"), "{label}");
        assert!(rest.starts_with("Java"), "{rest}");
        assert!(split_run_in_label("文本分类是标题").is_none());
        assert!(split_run_in_label("输出一个表格").is_none());
        let bytes = contents_pdf_named(
            b"BT \
/F1 9.5 Tf 1 0 0 1 74 420 Tm (I) Tj \
/F1 7.6 Tf 1 0 0 1 79 420 Tm (NSTRUCTION) Tj \
/F1 9.5 Tf 1 0 0 1 126 420 Tm (Add the square numbers.) Tj \
/F1 9.5 Tf 1 0 0 1 101 400 Tm (Text) Tj \
/F1 9.5 Tf 1 0 0 1 126 400 Tm (Java is a popular programming language.) Tj \
/F1 9.5 Tf 1 0 0 1 102 376 Tm (Text classification is a heading here.) Tj \
ET",
            "FranklinGothic-Book",
        );
        let painted = paint_translation(
            &bytes,
            &[
                (0, "指令：把这些平方数相加。".into()),
                (1, "文本 Java 是一种流行的编程语言。".into()),
                (2, "文本分类是这里的标题。".into()),
            ],
        );
        let mut java_x = None;
        let mut class_x = None;
        let mut class_label = None;
        for glyph in &painted.glyphs {
            if glyph.unicode == "J" {
                java_x = Some(glyph.matrix[4]);
            }
            if glyph.unicode == "分" {
                class_x = Some(glyph.matrix[4]);
            }
            if glyph.unicode == "文" && glyph.matrix[5] < 390.0 {
                class_label = Some(glyph.matrix[4]);
            }
        }
        let java_x = java_x.expect("Java");
        assert!(
            (java_x - 126.0).abs() < 4.0,
            "Java left the source body x: {java_x:.1}"
        );
        assert_prompt_labels_have_no_colon(&painted, java_x);
        assert_label_smaller_than_body(&painted, "令", "把");
        let rights = hanging_label_rights(&painted, java_x);
        assert!(
            rights.len() >= 2,
            "指令 and 文本 should both hang: {rights:?}"
        );
        let span = rights.iter().copied().fold(0.0f32, f32::max)
            - rights.iter().copied().fold(f32::MAX, f32::min);
        assert!(
            span < 1.5,
            "title-case 文本 is not on the label axis: {rights:?}"
        );
        assert!(
            rights.iter().all(|right| *right < java_x - 2.0),
            "label crossed Java: {rights:?} java {java_x:.1}"
        );
        let class_x = class_x.expect("分类");
        let class_label = class_label.expect("文本分类");
        assert!(
            (class_x - class_label).abs() < 12.0,
            "Text classification was split into a hanging label: 文 {class_label:.1} 分 {class_x:.1}"
        );
        assert_no_glyph_overlap(&painted);
    }

    #[test]
    fn output_format_stays_a_label_when_it_touches_the_body() {
        // FORMAT ends 2pt before Present. A gap test misses it; the small-caps
        // size change is what marks the label.
        let bytes = contents_pdf_named(
            b"BT \
/F1 9.5 Tf 1 0 0 1 66 400 Tm (O) Tj \
/F1 7.6 Tf 1 0 0 1 72 400 Tm (UTPUT FORMAT) Tj \
/F1 9.5 Tf 1 0 0 1 120 400 Tm (Present the text in two paragraphs.) Tj \
ET",
            "FranklinGothic-Book",
        );
        let painted = paint_translation(&bytes, &[(0, "输出格式：请以两段形式呈现文本。".into())]);
        let mut label_right = 0.0f32;
        let mut body_x = None;
        let mut label_size = None;
        let mut body_size = None;
        for glyph in &painted.glyphs {
            if glyph.unicode == "式" && glyph.font_size < 8.0 {
                label_right = label_right.max(glyph.bbox[0].max(glyph.bbox[2]));
                label_size = Some(glyph.font_size);
            }
            if glyph.unicode == "请" {
                body_x = Some(glyph.matrix[4]);
                body_size = Some(glyph.font_size);
            }
            if glyph.unicode == "：" && glyph.matrix[4] < 130.0 {
                panic!("输出格式 painted a colon at x={:.1}", glyph.matrix[4]);
            }
        }
        let body_x = body_x.expect("missing body");
        assert!(
            (body_x - 120.0).abs() < 4.0,
            "body left the source x: {body_x:.1}"
        );
        assert!(
            label_right < body_x - 1.5,
            "label right {label_right:.1} crossed the body at {body_x:.1}"
        );
        let (label_size, body_size) = (label_size.unwrap(), body_size.unwrap());
        assert!(
            label_size < body_size * 0.92,
            "label {label_size:.2} is not smaller than body {body_size:.2}"
        );
        assert_no_glyph_overlap(&painted);
    }

    #[test]
    fn stock_reports_keep_one_line_per_item() {
        let first = "Stock 2: Nvidia: sales are being propelled by consumer demand on large language models.";
        let second =
            "Stock 3: GX oil: demand of carbon based energy is dropping thanks to renewable sources.";
        let content = format!(
            "BT \
/F1 9.5 Tf 1 0 0 1 126 400 Tm ({first}) Tj \
/F1 9.5 Tf 1 0 0 1 126 386 Tm ({second}) Tj \
ET"
        );
        let bytes = contents_pdf_named(content.as_bytes(), "FranklinGothic-Book");
        let painted = paint_translation(
            &bytes,
            &[(
                0,
                "股票 2: 英伟达：销售额正受到大语言模型消费者需求的推动 股票 3: GX石油：得益于可再生能源的增长，碳基能源的需求正在下降"
                    .into(),
            )],
        );
        let mut heads: Vec<(f32, f32)> = painted
            .glyphs
            .iter()
            .filter(|glyph| glyph.unicode == "股")
            .map(|glyph| (glyph.matrix[4], glyph.matrix[5]))
            .collect();
        heads.sort_by(|left, right| right.1.total_cmp(&left.1));
        assert_eq!(heads.len(), 2, "stock heads: {heads:?}");
        assert!(
            (heads[0].1 - heads[1].1).abs() > 8.0,
            "股票2 and 股票3 share a line: {heads:?}"
        );
        assert!(
            heads.iter().all(|(x, _)| (*x - 126.0).abs() < 4.0),
            "an item left the source x: {heads:?}"
        );
        let ascii_colon = painted.glyphs.iter().any(|glyph| glyph.unicode == ":");
        assert!(!ascii_colon, "a stock head kept an ASCII colon");
        assert_no_glyph_overlap(&painted);
    }

    #[test]
    fn a_gold_bullet_does_not_paint_the_part_text_gold() {
        let bytes = contents_pdf_named(
            b"BT /F1 10 Tf \
0.8 0.651 0.349 rg \
1 0 0 1 72 500 Tm (- ) Tj \
0.148 g \
1 0 0 1 78 500 Tm (Part 1: Getting started with LLMs today) Tj \
1 0 0 1 96 486 Tm (lays the foundation for the later chapters.) Tj \
ET",
            "NewBaskerville-Italic",
        );
        let zh = "第 1 部分：入门（第 1–2 章）——本部分奠定基础。";
        let painted = paint_translation(&bytes, &[(0, zh.to_string())]);
        let mut gold = 0;
        let mut text = 0;
        for glyph in &painted.glyphs {
            if !glyph.font_name.starts_with("RPTCJK")
                && !glyph.unicode.chars().any(is_han_char)
                && glyph.unicode != "■"
                && glyph.unicode != "-"
            {
                continue;
            }
            let rgb = glyph.fill_color.components.first().copied().unwrap_or(0.0);
            let goldish = glyph.fill_color.components.first().copied().unwrap_or(0.0) > 0.5;
            if glyph.unicode == "■" || glyph.unicode == "-" {
                if goldish {
                    gold += 1;
                }
            } else if glyph.unicode.chars().any(is_han_char) {
                text += 1;
                assert!(
                    rgb < 0.4,
                    "han {} is gold {:?}",
                    glyph.unicode,
                    glyph.fill_color
                );
            }
        }
        assert!(gold >= 1, "marker lost its colour");
        assert!(text > 4, "part text missing");
        let italic = painted
            .glyphs
            .iter()
            .any(|glyph| glyph.unicode.chars().any(is_han_char) && glyph.matrix[2].abs() > 0.1);
        let roman = painted
            .glyphs
            .iter()
            .any(|glyph| glyph.unicode == "本" && glyph.matrix[2].abs() < 0.05);
        assert!(italic, "part lead should keep the italic shear");
        assert!(roman, "explanation after the em dash should be roman");
    }

    #[test]
    fn a_short_list_item_does_not_leave_a_hole_before_the_next() {
        let bytes = contents_pdf(
            b"BT /F1 10 Tf \
1 0 0 1 72 500 Tm (- Part one is a long item that wraps) Tj \
1 0 0 1 90 486 Tm (onto a second line of the same item) Tj \
1 0 0 1 90 472 Tm (and finishes on a third line here.) Tj \
1 0 0 1 72 458 Tm (- Chapter two follows immediately.) Tj \
ET",
        );
        let painted = paint_translation(
            &bytes,
            &[
                (0, "第 1 部分很短。".into()),
                (1, "第 2 章紧随其后。".into()),
            ],
        );
        let mut rows: Vec<(f32, String)> = Vec::new();
        for glyph in &painted.glyphs {
            if !glyph.unicode.chars().any(is_han_char)
                && glyph.unicode != "■"
                && glyph.unicode != "-"
            {
                continue;
            }
            if let Some(row) = rows
                .iter_mut()
                .find(|(y, _)| (*y - glyph.matrix[5]).abs() < 1.0)
            {
                row.1.push_str(&glyph.unicode);
            } else {
                rows.push((glyph.matrix[5], glyph.unicode.clone()));
            }
        }
        rows.sort_by(|left, right| right.0.total_cmp(&left.0));
        assert!(rows.len() >= 2, "{rows:?}");
        let gap = rows[0].0 - rows[1].0;
        assert!(gap < 24.0, "list hole is {gap}pt between {rows:?}");
    }

    fn paint_translation(bytes: &[u8], which: &[(usize, String)]) -> Extraction {
        PdfDocument::open_bytes(&paint_bytes(bytes, which))
            .unwrap()
            .extract()
    }

    fn paint_system_cjk(bytes: &[u8], which: &[(usize, String)]) -> Vec<u8> {
        paint_rewritten(bytes, which, false, None)
    }

    fn paint_bytes(bytes: &[u8], which: &[(usize, String)]) -> Vec<u8> {
        paint_rewritten(bytes, which, true, None)
    }

    fn paint_user_cjk(bytes: &[u8], which: &[(usize, String)], font: &str) -> Vec<u8> {
        paint_rewritten(bytes, which, false, Some(font))
    }

    fn paint_rewritten(
        bytes: &[u8],
        which: &[(usize, String)],
        box_font: bool,
        user_font: Option<&str>,
    ) -> Vec<u8> {
        let mut doc = PdfDocument::open_bytes(bytes).unwrap();
        let mut extraction = doc.extract();
        let segmentation = crate::segment::segment_placed(
            &extraction.glyphs,
            &crate::segment::SegmentFlags::default(),
            &extraction.regions,
            &extraction.pages,
        );
        for (id, reason) in &segmentation.kept {
            extraction.mark_kept(*id, reason.clone()).unwrap();
        }
        let mut chars: Vec<u32> = which
            .iter()
            .flat_map(|(_, text)| text.chars().map(|ch| ch as u32))
            .collect();
        chars.extend(
            "■—–API ：指令文本示例输出角色背景输入语气说明文字人设语调格式"
                .chars()
                .map(|ch| ch as u32),
        );
        for seg in &segmentation.segments {
            chars.extend(seg.text.chars().map(|ch| ch as u32));
        }
        let segments: Vec<_> = segmentation
            .segments
            .iter()
            .enumerate()
            .map(|(index, seg)| {
                let translated = which
                    .iter()
                    .find(|(slot, _)| *slot == index)
                    .map(|(_, text)| text.clone())
                    .unwrap_or_else(|| seg.text.clone());
                TranslatedSegment {
                    id: seg.id,
                    page_index: seg.page_index,
                    glyph_ids: seg.glyph_ids.clone(),
                    source: seg.text.clone(),
                    translated,
                }
            })
            .collect();
        doc.rewrite(
            &mut extraction,
            &TranslateReport {
                segments,
                calls: 0,
                cache_hits: 0,
            },
            &RewriteOptions {
                font_bytes: box_font.then(|| box_ttf(&chars)),
                cjk_serif: user_font.map(std::path::PathBuf::from),
                cjk_bold: user_font.map(std::path::PathBuf::from),
                ..RewriteOptions::default()
            },
        )
        .unwrap();
        doc.save_bytes().unwrap()
    }

    fn glyph_lines(extraction: &Extraction) -> Vec<String> {
        let mut glyphs: Vec<&Glyph> = extraction
            .glyphs
            .iter()
            .filter(|glyph| {
                glyph.font_name.contains("RPT") || glyph.unicode.chars().any(is_han_char)
            })
            .collect();
        glyphs.sort_by(|left, right| {
            right.matrix[5]
                .total_cmp(&left.matrix[5])
                .then(left.matrix[4].total_cmp(&right.matrix[4]))
        });
        let mut lines: Vec<Vec<&Glyph>> = Vec::new();
        for glyph in glyphs {
            let same = lines.last().is_some_and(|line: &Vec<&Glyph>| {
                (line[0].matrix[5] - glyph.matrix[5]).abs() < 1.5
            });
            if same {
                lines.last_mut().unwrap().push(glyph);
            } else {
                lines.push(vec![glyph]);
            }
        }
        lines
            .into_iter()
            .map(|line| line.iter().map(|glyph| glyph.unicode.as_str()).collect())
            .collect()
    }

    fn toc_column_pdf() -> Vec<u8> {
        let mut doc = Document::with_version("1.4");
        doc.reference_table.cross_reference_type = lopdf::xref::XrefType::CrossReferenceTable;
        let pages_id = doc.new_object_id();
        let widths: Vec<lopdf::Object> = (0..256).map(|_| lopdf::Object::Integer(500)).collect();
        let font = doc.add_object(dictionary! {
            "Type" => "Font",
            "Subtype" => "Type1",
            "BaseFont" => "Helvetica",
            "Encoding" => "WinAnsiEncoding",
            "FirstChar" => 0,
            "LastChar" => 255,
            "Widths" => widths,
        });
        let mut fonts = lopdf::Dictionary::new();
        fonts.set("F1", font);
        let mut resources = lopdf::Dictionary::new();
        resources.set("Font", fonts);
        // One TJ per row, matching a contents line whose page number shares the
        // title's operator. -1000 is a 12pt gap at 12pt: wide enough to detach
        // the number, narrow enough that it is not a second column.
        let content = b"BT /F1 12 Tf \
1 0 0 1 72 700 Tm [(Agents) -1000 (27)] TJ \
1 0 0 1 72 670 Tm [(Query generation, routing, and retrieval postprocessing) -1000 (228)] TJ \
ET"
        .to_vec();
        let content_id = doc.add_object(Stream::new(dictionary! {}, content));
        let page = doc.add_object(dictionary! {
            "Type" => "Page",
            "Parent" => pages_id,
            "MediaBox" => vec![0.into(), 0.into(), 612.into(), 792.into()],
            "Contents" => content_id,
            "Resources" => resources,
        });
        doc.set_object(
            pages_id,
            dictionary! {
                "Type" => "Pages",
                "Kids" => vec![page.into()],
                "Count" => 1,
            },
        );
        let catalog = doc.add_object(dictionary! {
            "Type" => "Catalog",
            "Pages" => pages_id,
        });
        doc.trailer.set("Root", catalog);
        let mut bytes = Vec::new();
        doc.save_to(&mut bytes).unwrap();
        bytes
    }

