    #[test]
    fn a_fraction_rule_follows_the_formula_and_a_footnote_rule_stays() {
        let src = b"q\n1 0 0 1 120.056 265.599 cm\n[]0 d 0 J 0.398 w 0 0 m 15.047 0 l S\nQ\n\
q\n1 0 0 1 126.601 264.493 cm\n[]0 d 0 J 0.339 w 0 0 m 8.503 0 l S\nQ\n\
q\n1 0 0 1 108 94.002 cm\n[]0 d 0 J 0.398 w 0 0 m 143.462 0 l S\nQ\n\
100 200 12 0.4 re S\n"
            .to_vec();
        let mut bytes = src.clone();
        let moved = shift_hairlines(
            &mut bytes,
            &[
                (116.0, 253.0, 140.0, 276.0, 49.7, 10.9),
                (96.0, 198.0, 116.0, 204.0, 5.0, -3.0),
            ],
            &[],
        );
        assert!(moved);
        let text = String::from_utf8(bytes.clone()).unwrap();
        assert!(text.contains("169.756 276.499 cm"), "{text}");
        assert!(text.contains("176.301 275.393 cm"), "{text}");
        assert!(text.contains("108 94.002 cm"), "{text}");
        assert!(text.contains("105 197 12 0.4 re"), "{text}");
        assert_eq!(bytes.len(), src.len());
    }

    #[test]
    fn a_rule_on_erased_text_is_blanked_and_a_moved_bar_stays() {
        let src = b"q\n1 0 0 1 120.056 265.599 cm\n[]0 d 0 J 0.398 w 0 0 m 15.047 0 l S\nQ\n\
q\n1 0 0 1 108 94.002 cm\n[]0 d 0 J 0.398 w 0 0 m 143.462 0 l S\nQ\n"
            .to_vec();
        let mut bytes = src.clone();
        assert!(blank_covered_hairlines(
            &mut bytes,
            &[(116.0, 253.0, 140.0, 276.0)],
            &[],
        ));
        let text = String::from_utf8(bytes.clone()).unwrap();
        assert!(!text.contains("120.056 265.599"), "{text}");
        assert!(text.contains("108 94.002 cm"), "{text}");
        assert_eq!(bytes.len(), src.len());

        let mut kept = src.clone();
        assert!(!blank_covered_hairlines(
            &mut kept,
            &[(116.0, 253.0, 140.0, 276.0)],
            &[(
                116.0 - 49.7,
                253.0 - 10.9,
                140.0 - 49.7,
                276.0 - 10.9,
                49.7,
                10.9
            )],
        ));
        assert_eq!(kept, src);

        // The SDE radical: `[]0 d` sits between `cm` and the stroke. A line
        // that moved onto this bar must not protect it.
        let radical =
            b"q\n1 0 0 1 378.142 483.647 cm\n[]0 d 0 J 0.299 w 0 0 m 26.108 0 l S\nQ\n".to_vec();
        let mut radical_bytes = radical.clone();
        assert!(
            blank_covered_hairlines(&mut radical_bytes, &[(370.0, 470.0, 420.0, 496.0)], &[],),
            "{}",
            String::from_utf8_lossy(&radical_bytes)
        );
        assert!(
            !String::from_utf8(radical_bytes).unwrap().contains("26.108"),
            "the bar on erased text stays"
        );
        // The bar is wider than any one erased glyph. Overlap across the
        // run is what puts it on the Chinese.
        let mut pieces = radical.clone();
        assert!(blank_covered_hairlines(
            &mut pieces,
            &[
                (376.0, 474.0, 386.0, 490.0),
                (386.0, 474.0, 396.0, 490.0),
                (396.0, 474.0, 406.0, 490.0),
            ],
            &[],
        ));
        assert!(!String::from_utf8(pieces).unwrap().contains("26.108"));
    }

    #[test]
    fn a_short_paragraph_pulls_the_display_equation_up() {
        let mut math: Vec<Glyph> = (0..6)
            .map(|index| {
                let mut glyph =
                    ink_glyph(30 + index, 108.0 + index as f32 * 12.0, 360.0, 10.0, "Q");
                glyph.font_name = "CMMI10".into();
                glyph
            })
            .collect();
        math.push({
            let mut label = ink_glyph(40, 200.0, 360.0, 10.0, "(1)");
            label.font_name = "CMR10".into();
            label
        });
        let mut glyphs = vec![
            ink_glyph(1, 108.0, 400.0, 10.0, "I"),
            ink_glyph(2, 108.0, 386.0, 10.0, "a"),
            ink_glyph(3, 108.0, 342.0, 10.0, "T"),
            ink_glyph(4, 108.0, 330.0, 10.0, "h"),
        ];
        glyphs.append(&mut math);
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![],
            glyphs,
            regions: vec![],
            diagnostics: vec![],
        };
        let by_id = glyph_index(&extraction.glyphs);
        let mut intro = test_draw(108.0, 400.0, 10.0, "输出矩阵的计算如下：", vec![1, 2]);
        intro.widths = vec![22.0; intro.text.chars().count()];
        // 18pt under the equation, the same gap d_k leaves above the next
        // sentence. The equation's old ink must not cap this line.
        let mut following = test_draw(108.0, 342.0, 10.0, "最常用的两种注意力函数", vec![3]);
        following.widths = vec![22.0; following.text.chars().count()];
        let mut after = test_draw(108.0, 330.0, 10.0, "点积注意力与我们的算法相同", vec![4]);
        after.widths = vec![22.0; after.text.chars().count()];
        let mut drawn = vec![intro, following, after];
        let shifts = close_column_holes(&mut drawn, &extraction, &by_id);
        let equation = shifts
            .iter()
            .find(|shift| shift.ids.contains(&30))
            .expect("display equation was left under the hole");
        assert!(
            equation.dy > 8.0,
            "equation dy {} did not close the gap",
            equation.dy
        );
        assert!(
            equation.ids.contains(&40),
            "equation tag stayed on the old baseline: {:?}",
            equation.ids
        );
        let next = drawn
            .iter()
            .find(|line| line.text.starts_with('最'))
            .unwrap();
        assert!(
            (next.y - (342.0 + equation.dy)).abs() < 1.5,
            "paragraph under the equation rose to {} while the equation rose {}",
            next.y - 342.0,
            equation.dy
        );
        let third = drawn
            .iter()
            .find(|line| line.text.starts_with('点'))
            .unwrap();
        assert!(
            (next.y - third.y - 12.0).abs() < 1.5,
            "lines under the equation closed up: {} then {}",
            next.y,
            third.y
        );
    }

    #[test]
    fn a_footnote_rule_does_not_stack_the_affiliation_and_venue() {
        // The abstract is shorter, so the column wants to pull the footnotes
        // up. The footnote rule used to absorb that pull, and †, ‡, and the
        // venue line still inherited it, so they painted on `*同等贡献`.
        let size = 9.0;
        let note_ids = vec![10, 11, 12, 13];
        let glyphs = vec![
            ink_glyph(1, 108.0, 220.0, size, "A"),
            ink_glyph(10, 108.0, 190.0, size, "*"),
            ink_glyph(11, 108.0, 178.0, size, "n"),
            ink_glyph(12, 108.0, 166.0, size, "o"),
            ink_glyph(13, 108.0, 154.0, size, "t"),
            ink_glyph(20, 108.0, 142.0, size, "†"),
            ink_glyph(21, 108.0, 130.0, size, "‡"),
            ink_glyph(22, 108.0, 112.0, size, "3"),
        ];
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![],
            glyphs,
            regions: vec![crate::glyph::PaintedRegion {
                page_index: 0,
                bbox: [108.0, 197.6, 251.5, 198.4],
                kind: "path".into(),
            }],
            diagnostics: vec![],
        };
        let by_id = glyph_index(&extraction.glyphs);
        let mut drawn = vec![
            test_draw(108.0, 320.0, size, "摘要在这里结束。", vec![1]),
            test_draw(
                108.0,
                190.0,
                size,
                "*同等贡献。作者排序随机。",
                note_ids.clone(),
            ),
            test_draw(
                108.0,
                178.0,
                size,
                "Illia 一起设计并实现了。",
                note_ids.clone(),
            ),
            test_draw(108.0, 166.0, size, "极大加速了我们的研究。", note_ids),
            test_draw(
                108.0,
                142.0,
                size,
                "†在 Google Brain 工作期间完成。",
                vec![20],
            ),
            test_draw(
                108.0,
                130.0,
                size,
                "‡在 Google Research 工作期间完成。",
                vec![21],
            ),
            test_draw(108.0, 112.0, size, "第31届神经信息处理系统大会。", vec![22]),
        ];
        let mut rules = Vec::new();
        close_column_holes_with(&mut drawn, &extraction, &by_id, &mut rules);
        let y_of = |prefix: &str| {
            drawn
                .iter()
                .find(|line| line.text.starts_with(prefix))
                .unwrap()
                .y
        };
        let star = y_of("*");
        let tail = y_of("极");
        let dagger = y_of("†");
        let double = y_of("‡");
        let venue = y_of("第");
        let abstract_y = y_of("摘");
        assert!(
            star > tail + size && tail > dagger + size * 0.4,
            "footnote order collapsed: abstract {abstract_y} star {star} tail {tail} dagger {dagger} double {double} venue {venue}"
        );
        assert!(
            dagger > double + size * 0.4 && double > venue + size * 0.4,
            "affiliation lines share a baseline: dagger {dagger} double {double} venue {venue}"
        );
        assert!(
            (star - dagger).abs() > size,
            "† landed on the star note: star {star} † {dagger}"
        );
        assert!(
            (star - venue).abs() > size && (dagger - venue).abs() > size * 0.4,
            "the venue line overlaps a footnote: star {star} † {dagger} venue {venue}"
        );
        assert!(
            abstract_y - star < size * 4.0,
            "the footnote stayed under the English rule, gap {}",
            abstract_y - star
        );
        let rule = rules
            .iter()
            .find(|rule| (rule.y - 198.0).abs() < 1.0)
            .expect("footnote rule was left on the English baseline");
        assert!(
            (rule.dy - (star - 190.0)).abs() < 1.0,
            "rule dy {} did not follow the note to {star}",
            rule.dy
        );
        let painted = rule.y + rule.dy;
        assert!(
            abstract_y - painted > size * 1.5,
            "footnote rule sits on the line above it: abstract {abstract_y} rule {painted}"
        );
    }

    #[test]
    fn a_tight_footnote_rule_keeps_air_under_the_intro() {
        // The Chinese intro is shorter, so the closer pulls the note up to
        // the English gap. That gap is only a few points, and the rule then
        // cuts the last intro line.
        let size = 10.0;
        let glyphs = vec![
            ink_glyph(1, 108.0, 192.0, size, "A"),
            ink_glyph(10, 108.0, 180.0, size, "*"),
            ink_glyph(20, 108.0, 168.0, size, "†"),
        ];
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![],
            glyphs,
            regions: vec![crate::glyph::PaintedRegion {
                page_index: 0,
                bbox: [108.0, 187.6, 251.5, 188.4],
                kind: "path".into(),
            }],
            diagnostics: vec![],
        };
        let by_id = glyph_index(&extraction.glyphs);
        let mut drawn = vec![
            test_draw(108.0, 250.0, size, "的界限。", vec![1]),
            test_draw(
                108.0,
                180.0,
                size,
                "*同等贡献。列表顺序是随机的。",
                vec![10],
            ),
            test_draw(
                108.0,
                168.0,
                size,
                "†在 Google Brain 期间完成的工作。",
                vec![20],
            ),
        ];
        let mut rules = Vec::new();
        close_column_holes_with(&mut drawn, &extraction, &by_id, &mut rules);
        let y_of = |prefix: &str| {
            drawn
                .iter()
                .find(|line| line.text.starts_with(prefix))
                .unwrap()
                .y
        };
        let intro = y_of("的");
        let star = y_of("*");
        let dagger = y_of("†");
        let rule = rules
            .iter()
            .find(|rule| (rule.y - 188.0).abs() < 1.0)
            .expect("footnote rule");
        let painted = rule.y + rule.dy;
        assert!(
            intro - painted >= size * 1.7,
            "rule cleared only {:.1}pt under the intro at {intro}",
            intro - painted
        );
        assert!(
            painted > star + size * 0.3,
            "rule dropped into the note: rule {painted} star {star}"
        );
        assert!(
            star > dagger + size * 0.4,
            "† stacked on the star note: star {star} † {dagger}"
        );
    }

    #[test]
    fn an_author_name_stays_in_its_column_under_the_title() {
        // The title covers the middle column. Closing the vacant gap under
        // it used to lift only that name, so `诺姆·沙泽尔` sat alone above
        // the author grid.
        let size = 10.0;
        let glyphs = vec![
            ink_glyph(1, 200.0, 640.0, 14.0, "Attention"),
            ink_glyph(2, 120.0, 560.0, size, "Ashish"),
            ink_glyph(3, 240.0, 560.0, size, "Noam"),
            ink_glyph(4, 350.0, 560.0, size, "Niki"),
            ink_glyph(5, 450.0, 560.0, size, "Jakob"),
        ];
        let extraction = Extraction {
            coordinate_space: "user",
            pages: vec![],
            glyphs,
            regions: vec![],
            diagnostics: vec![],
        };
        let by_id = glyph_index(&extraction.glyphs);
        let mut drawn = vec![
            test_draw(200.0, 640.0, 14.0, "Attention Is All You Need", vec![1]),
            test_draw(120.0, 560.0, size, "阿什什·瓦斯瓦尼", vec![2]),
            test_draw(240.0, 560.0, size, "诺姆·沙泽尔", vec![3]),
            test_draw(350.0, 560.0, size, "尼基·帕尔玛", vec![4]),
            test_draw(450.0, 560.0, size, "雅各布·乌什科雷特", vec![5]),
        ];
        close_column_holes(&mut drawn, &extraction, &by_id);
        let y_of = |text: &str| drawn.iter().find(|line| line.text == text).unwrap().y;
        let noam = y_of("诺姆·沙泽尔");
        let ashish = y_of("阿什什·瓦斯瓦尼");
        let niki = y_of("尼基·帕尔玛");
        assert!(
            (noam - ashish).abs() < 0.6 && (noam - niki).abs() < 0.6,
            "middle name left the row: noam {noam} ashish {ashish} niki {niki}"
        );
        assert!(
            y_of("Attention Is All You Need") - noam > 40.0,
            "middle name rose into the title gap"
        );
    }

